window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"sl-40667","module":"shuliang","prompt":"甲种卡车每次可运5吨货物，耗油14升；乙种卡车每次可运2吨货物，耗油6升。现要运送45吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["122","133","126","132"],"answer":2,"explanation":"甲车每吨耗油14/5升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：9车次运45吨，余0吨用乙车0次，共耗油126升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40668","module":"shuliang","prompt":"某单位组织100人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["887","1055","960","1200"],"answer":2,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为960元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40669","module":"shuliang","prompt":"已知等差数列的前10项和为270，前20项和为940，则该数列的公差是多少？","options":["3","6","4","1"],"answer":2,"explanation":"S20−2×S10=(940)−2×(270)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40670","module":"shuliang","prompt":"某商品按定价出售每件可赚80元，若按定价的8折出售，每件将亏损20元。该商品的进价是多少元？","options":["433","420","396","100"],"answer":1,"explanation":"设进价为C，定价为C+80；8折售价为8/10×(C+80)=C−20，解得C=420元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40671","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才5岁。”乙对甲说：“当我到你这么大时，你就29岁了。”甲今年多少岁？","options":["13","21","22","19"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙5岁，即乙现在为x+d；乙到甲现在这么大时甲29岁，即甲现在为y−d。由y−d−(x+d)=d得d=(29−5)÷3=8，甲今年=29−8=21岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40672","module":"shuliang","prompt":"袋中有3个红球和7个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/2","7/10","1","3/10"],"answer":3,"explanation":"共有10个球，红球3个，取到红球的概率为3/10。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40673","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖84件。售价每提高1元，每天少卖2件。要使每天利润最大，售价应定为每件多少元？","options":["60","69","64","66"],"answer":3,"explanation":"设售价提高k元，每天利润=(30+k)×(84−2k)，是关于k的二次函数，当k=6时最大，此时售价=60+6=66元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40674","module":"shuliang","prompt":"今年甲的年龄是乙的5倍，7年后甲的年龄是乙的4倍。乙今年多少岁？","options":["21","23","19","7"],"answer":0,"explanation":"设乙今年x岁，则甲为5x岁；7年后：5x+7=4(x+7)，解得x=21岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40675","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需50小时，逆流需62小时，两码头相距1550千米。该轮船在静水中的速度是多少千米/小时？","options":["28","3","31","27"],"answer":0,"explanation":"顺流速度=1550÷50=31千米/小时，逆流速度=1550÷62=25千米/小时；静水速度=(31+25)÷2=28千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40676","module":"shuliang","prompt":"一项工程，甲先做10天、乙再做8天恰好完成；若乙先做10天、甲再做8天也恰好完成。两人合作，需要多少天完成？","options":["9","18","2","10"],"answer":0,"explanation":"设甲每天完成x、乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=18÷2=9天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40677","module":"shuliang","prompt":"A接水需要5分钟，B接水需要6分钟，C接水需要9分钟，D接水需要12分钟，E接水需要3分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["48","90","81","35"],"answer":0,"explanation":"让用时短的人先接水可使总等待时间最短。按3、5、6、9、12的顺序，总等待=3×4+5×3+6×2+9×1+12×0=48分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40678","module":"shuliang","prompt":"一个长方体的长、宽、高分别为6厘米、3厘米、11厘米，它的表面积是多少平方厘米？","options":["234","198","20","40"],"answer":0,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(18+33+66)=234平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40679","module":"shuliang","prompt":"4个正整数之和为35（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["8","10","7","9"],"answer":3,"explanation":"最大数最小时各数尽量平均，35÷4=8余3，故最大数至少为9（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40680","module":"shuliang","prompt":"一个平底锅每次最多可以烙3张饼，每张饼两面都要烙，每面需要3分钟。烙5张饼最少需要多少分钟？","options":["10","30","15","12"],"answer":3,"explanation":"共需烙5×2=10面，每次最多烙3面，至少4锅次，最少4×3=12分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40681","module":"shuliang","prompt":"某商品按进价加价80%定价，然后按6折出售，仍可获利。该商品的利润率是多少？","options":["12%","48%","8%","17%"],"answer":2,"explanation":"设进价为100，售价=100×(1+80%)×6/10=108，利润率=108−100=8%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40682","module":"shuliang","prompt":"某商品进价每件50元，售价每件90元时每天可卖176件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["90","95","91","92"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(176−4k)，是关于k的二次函数，当k=2时最大，此时售价=90+2=92元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40683","module":"shuliang","prompt":"一个长方形的长为19米，宽为25米，它的面积是多少平方米？","options":["494","88","44","475"],"answer":3,"explanation":"长方形面积=长×宽=19×25=475平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40684","module":"shuliang","prompt":"一个平底锅每次最多可以烙2张饼，每张饼两面都要烙，每面需要4分钟。烙7张饼最少需要多少分钟？","options":["31","56","32","28"],"answer":3,"explanation":"共需烙7×2=14面，每次最多烙2面，至少7锅次，最少7×4=28分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40685","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有26人，参加羽毛球赛的有35人，参加乒乓球赛的有29人；同时参加篮球和羽毛球的有8人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有6人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["58","54","50","70"],"answer":1,"explanation":"只参加篮球=26−8−10+4=12人；同理只参加羽毛球=25人，只参加乒乓球=17人；合计12+25+17=54人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40686","module":"shuliang","prompt":"两个正数的和为32，要使它们的乘积最大，则最大的乘积是多少？","options":["261","32","256","255"],"answer":2,"explanation":"两数和一定时，两数相等时乘积最大，均为32÷2=16，最大乘积=16×16=256。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40687","module":"shuliang","prompt":"已知等差数列的首项为9，公差为2，则它的第13项是多少？","options":["33","35","31","34"],"answer":0,"explanation":"等差数列第n项=首项+(n−1)×公差=9+(13-1)×2=33。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40688","module":"shuliang","prompt":"某商品进价每件50元，售价每件70元时每天可卖108件。售价每提高1元，每天少卖2件。要使每天利润最大，售价应定为每件多少元？","options":["87","90","85","70"],"answer":0,"explanation":"设售价提高k元，每天利润=(20+k)×(108−2k)，是关于k的二次函数，当k=17时最大，此时售价=70+17=87元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40689","module":"shuliang","prompt":"A接水需要7分钟，B接水需要12分钟，C接水需要5分钟，D接水需要9分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["68","78","38","33"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按5、7、9、12的顺序，总等待=5×3+7×2+9×1+12×0=38分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40690","module":"shuliang","prompt":"一项工程，王师傅先做7天、赵师傅再做13天恰好完成；若赵师傅先做7天、王师傅再做13天也恰好完成。两人合作，需要多少天完成？","options":["11","20","6","10"],"answer":3,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=20÷2=10天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40691","module":"shuliang","prompt":"数列{aₙ}满足a₁=2，aₙ₊₁=2aₙ+1，则a6等于多少？","options":["100","95","92","96"],"answer":1,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(2+1)×2^(n−1)，a6=(2+1)×32−1=95。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40692","module":"shuliang","prompt":"一项工程，张师傅的工作效率是李师傅的3倍，两人合作9天完成。若由张师傅单独做，需要多少天完成？","options":["11","9","15","12"],"answer":3,"explanation":"设李师傅每天完成1份，则张师傅每天完成3份，两人合作每天4份，工程总量为9×4=36份；张师傅单独做需36÷3=12天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40693","module":"shuliang","prompt":"一列火车长137米，以每秒32米的速度通过一座长1600米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["50","4","54","55"],"answer":2,"explanation":"火车完全过桥需行驶137+1600=1737米，时间=1737÷32=54秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40694","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是57立方分米。圆锥的体积是多少立方分米？","options":["19","57","28","114"],"answer":0,"explanation":"等底等高的圆锥体积是圆柱的1/3，即57÷3=19立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40695","module":"shuliang","prompt":"一个长方形的长为6米，宽为15米，它的面积是多少平方米？","options":["21","42","90","96"],"answer":2,"explanation":"长方形面积=长×宽=6×15=90平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40696","module":"shuliang","prompt":"某小组共有11名成员，现从中随机选出5名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["462","336","126","339"],"answer":1,"explanation":"从11人中选5人共C(11,5)=462种；甲、乙都不入选有C(9,5)=126种；故至少一人入选共462−126=336种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40697","module":"shuliang","prompt":"一项工程，张师傅单独做需要9天完成，李师傅单独做需要24天完成。现两人合作3天后，剩余部分由李师傅单独完成，还需要多少天？","options":["14","21","13","24"],"answer":2,"explanation":"两人每天合作完成1/9+1/24=(9+24)/216，3天完成99/216，剩117/216；李师傅每天完成1/24，还需24×117/216=13天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40698","module":"shuliang","prompt":"一个圆的半径为20厘米（π取3.14），它的面积是多少平方厘米？","options":["125","1256","1290","1241"],"answer":1,"explanation":"圆的面积=πr²=3.14×20×20=1256平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40699","module":"shuliang","prompt":"客车、货车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地43千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地15千米处。问A、B两地相距多少千米？","options":["93","72","49","129"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且客车行43千米，故第二次相遇时客车共行129千米。129大于一个全程而小于两个全程，说明客车已从B地折返，其位置距A地为2S−129（S为全程）。由2S−129=15，解得S=72千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40700","module":"shuliang","prompt":"5个正整数之和为64（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["14","13","11","12"],"answer":1,"explanation":"最大数最小时各数尽量平均，64÷5=12余4，故最大数至少为13（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40701","module":"shuliang","prompt":"一个长方形的长为6米，宽为24米，它的面积是多少平方米？","options":["30","60","144","150"],"answer":2,"explanation":"长方形面积=长×宽=6×24=144平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40702","module":"shuliang","prompt":"A接水需要11分钟，B接水需要3分钟，C接水需要12分钟，D接水需要10分钟，E接水需要5分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["103","58","94","41"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按3、5、10、11、12的顺序，总等待=3×4+5×3+10×2+11×1+12×0=58分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40703","module":"shuliang","prompt":"某淘汰赛共有16支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["15","16","8","30"],"answer":0,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰15支，故共需15场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40704","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行36千米，按原路返回时每小时行45千米。该车往返全程的平均速度是多少千米/小时？","options":["40","41","39","45"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/36+1/45)=2×36×45÷(36+45)=40千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40705","module":"shuliang","prompt":"某淘汰赛共有14支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["7","14","13","16"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰13支，故共需13场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40706","module":"shuliang","prompt":"两个正数的和为16，要使它们的乘积最大，则最大的乘积是多少？","options":["61","16","68","64"],"answer":3,"explanation":"两数和一定时，两数相等时乘积最大，均为16÷2=8，最大乘积=8×8=64。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40707","module":"shuliang","prompt":"某淘汰赛共有10支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["5","10","9","12"],"answer":2,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰9支，故共需9场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40708","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第87面彩旗是什么颜色？","options":["丙","乙","甲","丁"],"answer":1,"explanation":"周期为5，87÷5=17余2，第87面旗对应周期中的第2个，即“乙”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40709","module":"shuliang","prompt":"一项工程，老周先做12天、老吴再做14天恰好完成；若老吴先做12天、老周再做14天也恰好完成。两人合作，需要多少天完成？","options":["26","13","2","14"],"answer":1,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=26÷2=13天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40710","module":"shuliang","prompt":"彩旗按“红、白、黑、蓝”的顺序循环排列，第108面彩旗是什么颜色？","options":["红","蓝","黑","白"],"answer":1,"explanation":"周期为4，108÷4=27余0，第108面旗对应周期中的第4个，即“蓝”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40711","module":"shuliang","prompt":"一列火车长287米，以每秒29米的速度通过一座长2697米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["93","9","102","104"],"answer":2,"explanation":"火车完全过桥需行驶287+2697=2984米，时间=2984÷29=102秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40712","module":"shuliang","prompt":"甲、乙、丙、丁、戊、己六名同学排成一排表演节目，其中甲、乙、丙三人必须相邻，共有多少种不同的排法？","options":["720","144","120","72"],"answer":1,"explanation":"把甲、乙、丙捆绑为一个整体，与丁、戊、己共4个元素全排列，有4!=24种；三人内部全排列3!=6种；共24×6=144种。","exam":"通用基础","__sub":"排列组合","diff":3},{"id":"sl-40713","module":"shuliang","prompt":"两个数的和是80，差是40。这两个数中较大的数是多少？","options":["0","80","60","41"],"answer":2,"explanation":"小数=（和−差）÷2=20，大数=（和+差）÷2=60。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40714","module":"shuliang","prompt":"一项工程，师傅甲先做16天、师傅乙再做10天恰好完成；若师傅乙先做16天、师傅甲再做10天也恰好完成。两人合作，需要多少天完成？","options":["6","26","13","14"],"answer":2,"explanation":"设师傅甲每天完成x、师傅乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=26÷2=13天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40715","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有22人，参加羽毛球赛的有29人，参加乒乓球赛的有33人；同时参加篮球和羽毛球的有7人，参加篮球和乒乓球的有9人，参加羽毛球和乒乓球的有11人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["46","52","48","63"],"answer":2,"explanation":"只参加篮球=22−7−9+6=12人；同理只参加羽毛球=17人，只参加乒乓球=19人；合计12+17+19=48人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40716","module":"shuliang","prompt":"已知等差数列的前10项和为265，前20项和为1030，则该数列的公差是多少？","options":["4","6","5","1"],"answer":2,"explanation":"S20−2×S10=(1030)−2×(265)=500=100d（第11到20项之和比前10项之和多100d），故d=5。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40717","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有22人，参加物理组的有35人，参加化学组的有40人；同时参加数学和物理的有8人，参加数学和化学的有10人，参加物理和化学的有12人，三个组都参加的有3人。三个组至少参加一个的共有多少人？","options":["71","97","70","69"],"answer":2,"explanation":"由三集合容斥公式：至少参加一个=22+35+40−8−10−12+3=70人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40718","module":"shuliang","prompt":"一个平底锅每次最多可以烙3张饼，每张饼两面都要烙，每面需要2分钟。烙4张饼最少需要多少分钟？","options":["7","16","8","6"],"answer":3,"explanation":"共需烙4×2=8面，每次最多烙3面，至少3锅次，最少3×2=6分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40719","module":"shuliang","prompt":"某班共有59人，参加数学竞赛的有30人，参加作文竞赛的有24人，参加英语竞赛的有21人；同时参加数学和作文的有9人，参加数学和英语的有10人，参加作文和英语的有6人，三项都参加的有4人。三项竞赛都不参加的有多少人？","options":["59","7","25","5"],"answer":3,"explanation":"至少参加一项的有30+24+21−9−10−6+4=54人，都不参加的有59−54=5人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40720","module":"shuliang","prompt":"今年父子二人年龄之和是100岁，父亲年龄是儿子年龄的3倍。父亲今年多少岁？","options":["72","25","80","75"],"answer":3,"explanation":"儿子年龄为1份，父亲为3份，共4份；儿子=100÷4=25岁，父亲=3×25=75岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40721","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油12升；乙种卡车每次可运3吨货物，耗油7升。现要运送36吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["72","74","69","84"],"answer":0,"explanation":"甲车每吨耗油12/6升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：6车次运36吨，余0吨用乙车0次，共耗油72升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40722","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才4岁。”乙对甲说：“当我到你这么大时，你就16岁了。”甲今年多少岁？","options":["10","8","15","12"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙4岁，即乙现在为x+d；乙到甲现在这么大时甲16岁，即甲现在为y−d。由y−d−(x+d)=d得d=(16−4)÷3=4，甲今年=16−4=12岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40723","module":"shuliang","prompt":"一项工程，张师傅先做19天、李师傅再做9天恰好完成；若李师傅先做19天、张师傅再做9天也恰好完成。两人合作，需要多少天完成？","options":["15","28","10","14"],"answer":3,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=28÷2=14天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40724","module":"shuliang","prompt":"在一个边长为26厘米的正方形纸片内，剪一个最大的圆（圆的直径等于正方形边长，π取3.14）。剩下的纸片面积是多少平方厘米？","options":["146","676","153","139"],"answer":0,"explanation":"正方形面积=676平方厘米，最大圆半径为13厘米，圆面积=3.14×13²=530平方厘米，剩余=676−530=146平方厘米。","exam":"通用基础","__sub":"几何问题","diff":3},{"id":"sl-40725","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供19头牛吃12天，或供26头牛吃8天。若放29头牛，可以吃多少天？","options":["8","10","6","7"],"answer":3,"explanation":"每天长草量=(26×8−19×12)÷(8−12)=5份，原有草量=19×12−5×12=168份；29头牛每天净消耗29−5=24份，可吃168÷24=7天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40726","module":"shuliang","prompt":"小明在小红后方10千米处，两人同时同向出发。小明每小时行43千米，小红每小时行41千米，经过多少小时小明追上小红？","options":["5","6","7","10"],"answer":0,"explanation":"每小时小明比小红多行43-41=2千米，追及时间=10÷2=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40727","module":"shuliang","prompt":"一项工程，一队单独做需要14天完成，二队单独做需要21天完成。现两人合作4天后，剩余部分由二队单独完成，还需要多少天？","options":["21","17","14","11"],"answer":3,"explanation":"两人每天合作完成1/14+1/21=(14+21)/294，4天完成140/294，剩154/294；二队每天完成1/21，还需21×154/294=11天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40728","module":"shuliang","prompt":"一项工程，甲单独做需要10天完成，乙单独做需要15天完成。两人（队）合作，需要多少天完成？","options":["25","6","5","13"],"answer":1,"explanation":"把工程总量看作1，两人效率之和为1/10+1/15=(10+15)/150，合作需要150÷(10+15)=6天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40729","module":"shuliang","prompt":"把75个名额按5:8:2的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["40","10","65","35"],"answer":0,"explanation":"总份数=5+8+2=15，每份75÷15=5个，最多的班级分得8×5=40个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40730","module":"shuliang","prompt":"某商品进价300元，售价519元。该商品的利润率是多少？","options":["146%","76%","69%","73%"],"answer":3,"explanation":"利润=519−300=219元，利润率=219÷300×100%=73%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40731","module":"shuliang","prompt":"一项工程，老周先做16天、老吴再做6天恰好完成；若老吴先做16天、老周再做6天也恰好完成。两人合作，需要多少天完成？","options":["11","22","10","12"],"answer":0,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=22÷2=11天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40732","module":"shuliang","prompt":"一个长方形的长为20米，宽为4米，它的周长是多少米？","options":["48","80","24","50"],"answer":0,"explanation":"长方形周长=2×（长+宽）=2×(20+4)=48米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40733","module":"shuliang","prompt":"轿车、面包车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地73千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地33千米处。问A、B两地相距多少千米？","options":["98","144","126","219"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且轿车行73千米，故第二次相遇时轿车共行219千米。219大于一个全程而小于两个全程，说明轿车已从B地折返，其位置距A地为2S−219（S为全程）。由2S−219=33，解得S=126千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40734","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有27人，参加羽毛球赛的有20人，参加乒乓球赛的有24人；同时参加篮球和羽毛球的有8人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有10人，三项都参加的有3人。只参加其中一项比赛的有多少人？","options":["24","26","22","46"],"answer":0,"explanation":"只参加篮球=27−8−10+3=12人；同理只参加羽毛球=5人，只参加乒乓球=7人；合计12+5+7=24人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40735","module":"shuliang","prompt":"今年父子二人年龄之和是69岁，父亲年龄是儿子年龄的2倍。父亲今年多少岁？","options":["23","46","49","41"],"answer":1,"explanation":"儿子年龄为1份，父亲为2份，共3份；儿子=69÷3=23岁，父亲=2×23=46岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40736","module":"shuliang","prompt":"已知等比数列的首项为3，公比为2，则它的第7项是多少？","options":["192","384","96","194"],"answer":0,"explanation":"等比数列第n项=首项×公比^(n−1)=3×2^(7-1)=192。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40737","module":"shuliang","prompt":"一项工程，一队先做19天、二队再做17天恰好完成；若二队先做19天、一队再做17天也恰好完成。两人合作，需要多少天完成？","options":["2","36","18","19"],"answer":2,"explanation":"设一队每天完成x、二队每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=36÷2=18天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40738","module":"shuliang","prompt":"某班共有57人，参加数学竞赛的有22人，参加作文竞赛的有22人，参加英语竞赛的有23人；同时参加数学和作文的有8人，参加数学和英语的有8人，参加作文和英语的有5人，三项都参加的有2人。三项竞赛都不参加的有多少人？","options":["13","9","21","57"],"answer":1,"explanation":"至少参加一项的有22+22+23−8−8−5+2=48人，都不参加的有57−48=9人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40739","module":"shuliang","prompt":"一项工程，一队的工作效率是二队的3倍，两人合作30天完成。若由一队单独做，需要多少天完成？","options":["30","40","43","38"],"answer":1,"explanation":"设二队每天完成1份，则一队每天完成3份，两人合作每天4份，工程总量为30×4=120份；一队单独做需120÷3=40天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40740","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才20岁。”乙对甲说：“当我到你这么大时，你就38岁了。”甲今年多少岁？","options":["30","26","34","32"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙20岁，即乙现在为x+d；乙到甲现在这么大时甲38岁，即甲现在为y−d。由y−d−(x+d)=d得d=(38−20)÷3=6，甲今年=38−6=32岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40741","module":"shuliang","prompt":"已知等差数列的首项为8，公差为5，则它的前19项之和是多少？","options":["1004","1862","1014","1007"],"answer":3,"explanation":"第19项=8+(19-1)×5=98，前19项和=n×(首项+末项)÷2=19×(8+98)÷2=1007。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40742","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需11小时，逆流需27小时，两码头相距297千米。该轮船在静水中的速度是多少千米/小时？","options":["8","19","27","17"],"answer":1,"explanation":"顺流速度=297÷11=27千米/小时，逆流速度=297÷27=11千米/小时；静水速度=(27+11)÷2=19千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40743","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖100件。售价每提高1元，每天少卖2件。要使每天利润最大，售价应定为每件多少元？","options":["70","73","67","60"],"answer":0,"explanation":"设售价提高k元，每天利润=(30+k)×(100−2k)，是关于k的二次函数，当k=10时最大，此时售价=60+10=70元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40744","module":"shuliang","prompt":"两个数的和是94，差是22。这两个数中较大的数是多少？","options":["58","69","25","94"],"answer":0,"explanation":"小数=（和−差）÷2=36，大数=（和+差）÷2=58。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40745","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行24千米，按原路返回时每小时行40千米。该车往返全程的平均速度是多少千米/小时？","options":["30","32","31","29"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/24+1/40)=2×24×40÷(24+40)=30千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40746","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有36人，参加物理组的有26人，参加化学组的有28人；同时参加数学和物理的有7人，参加数学和化学的有5人，参加物理和化学的有9人，三个组都参加的有4人。三个组至少参加一个的共有多少人？","options":["69","90","76","73"],"answer":3,"explanation":"由三集合容斥公式：至少参加一个=36+26+28−7−5−9+4=73人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40747","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供17头牛吃18天，或供25头牛吃9天。若放45头牛，可以吃多少天？","options":["6","4","3","7"],"answer":1,"explanation":"每天长草量=(25×9−17×18)÷(9−18)=9份，原有草量=17×18−9×18=144份；45头牛每天净消耗45−9=36份，可吃144÷36=4天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40748","module":"shuliang","prompt":"某商品按进价加价50%定价，然后按6折出售，仍可获利。该商品的利润率是多少？","options":["-10%","30%","-9%","-1%"],"answer":0,"explanation":"设进价为100，售价=100×(1+50%)×6/10=90，利润率=90−100=-10%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40749","module":"shuliang","prompt":"某班共有60人，参加数学竞赛的有18人，参加作文竞赛的有24人，参加英语竞赛的有26人；同时参加数学和作文的有5人，参加数学和英语的有5人，参加作文和英语的有5人，三项都参加的有5人。三项竞赛都不参加的有多少人？","options":["2","5","15","60"],"answer":0,"explanation":"至少参加一项的有18+24+26−5−5−5+5=58人，都不参加的有60−58=2人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40750","module":"shuliang","prompt":"4个正整数之和为58（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["15","18","14","16"],"answer":0,"explanation":"最大数最小时各数尽量平均，58÷4=14余2，故最大数至少为15（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40751","module":"shuliang","prompt":"今年父子二人年龄之和是108岁，父亲年龄是儿子年龄的3倍。父亲今年多少岁？","options":["77","27","85","81"],"answer":3,"explanation":"儿子年龄为1份，父亲为3份，共4份；儿子=108÷4=27岁，父亲=3×27=81岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40752","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是48立方分米。圆锥的体积是多少立方分米？","options":["96","48","24","16"],"answer":3,"explanation":"等底等高的圆锥体积是圆柱的1/3，即48÷3=16立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40753","module":"shuliang","prompt":"甲数是乙数的4倍，两数之和是130。乙数是多少？","options":["21","104","29","26"],"answer":3,"explanation":"乙数为1份，甲数为4份，共5份；乙数=130÷5=26。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40754","module":"shuliang","prompt":"数列{aₙ}满足a₁=1，aₙ₊₁=2aₙ+1，则a7等于多少？","options":["126","131","127","128"],"answer":2,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(1+1)×2^(n−1)，a7=(1+1)×64−1=127。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40755","module":"shuliang","prompt":"两个正数的和为18，要使它们的乘积最大，则最大的乘积是多少？","options":["18","81","86","80"],"answer":1,"explanation":"两数和一定时，两数相等时乘积最大，均为18÷2=9，最大乘积=9×9=81。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40756","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油12升；乙种卡车每次可运2吨货物，耗油5升。现要运送72吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["180","112","102","108"],"answer":3,"explanation":"甲车每吨耗油12/8升，乙车每吨耗油5/2升，甲车更省。尽量用甲车：9车次运72吨，余0吨用乙车0次，共耗油108升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40757","module":"shuliang","prompt":"某商品进价每件20元，售价每件50元时每天可卖336件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["60","67","63","50"],"answer":2,"explanation":"设售价提高k元，每天利润=(30+k)×(336−6k)，是关于k的二次函数，当k=13时最大，此时售价=50+13=63元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40758","module":"shuliang","prompt":"一个长方体的长、宽、高分别为12厘米、5厘米、7厘米，它的表面积是多少平方厘米？","options":["48","420","24","358"],"answer":3,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(60+35+84)=358平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40759","module":"shuliang","prompt":"袋中有3个红球和5个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["3/8","5/8","1","1/2"],"answer":0,"explanation":"共有8个球，红球3个，取到红球的概率为3/8。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40760","module":"shuliang","prompt":"两个正数的和为34，要使它们的乘积最大，则最大的乘积是多少？","options":["34","289","293","287"],"answer":1,"explanation":"两数和一定时，两数相等时乘积最大，均为34÷2=17，最大乘积=17×17=289。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40761","module":"shuliang","prompt":"某商场促销“满200减40”，小明购买了标价1000元的商品（满足优惠条件）。实际付款相当于打几折？","options":["7折","9折","8折","2折"],"answer":2,"explanation":"优惠后实付1000−5×40=800元，800÷1000=4/5，相当于打8折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40762","module":"shuliang","prompt":"时钟3点30分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["68","88","75","105"],"answer":2,"explanation":"时针与12点方向夹角为30×3+0.5×30=105.0度，分针与12点方向夹角为6×30=180度，两针夹角为75度，取小于180度的角为75.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40763","module":"shuliang","prompt":"6个正整数之和为50（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","9","7","8"],"answer":1,"explanation":"最大数最小时各数尽量平均，50÷6=8余2，故最大数至少为9（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40764","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有27人，参加羽毛球赛的有28人，参加乒乓球赛的有29人；同时参加篮球和羽毛球的有8人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有11人，三项都参加的有2人。只参加其中一项比赛的有多少人？","options":["32","37","29","57"],"answer":0,"explanation":"只参加篮球=27−8−10+2=11人；同理只参加羽毛球=11人，只参加乒乓球=10人；合计11+11+10=32人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40765","module":"shuliang","prompt":"袋中有4个红球和3个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1","3/7","4/7","1/2"],"answer":2,"explanation":"共有7个球，红球4个，取到红球的概率为4/7。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40766","module":"shuliang","prompt":"一项工程，老周先做9天、老吴再做17天恰好完成；若老吴先做9天、老周再做17天也恰好完成。两人合作，需要多少天完成？","options":["8","26","13","14"],"answer":2,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=26÷2=13天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40767","module":"shuliang","prompt":"一项工程，甲单独做需要9天完成，乙单独做需要30天完成。现两人合作3天后，剩余部分由乙单独完成，还需要多少天？","options":["30","27","19","17"],"answer":3,"explanation":"两人每天合作完成1/9+1/30=(9+30)/270，3天完成117/270，剩153/270；乙每天完成1/30，还需30×153/270=17天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40768","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供19头牛吃15天，或供26头牛吃8天。若放31头牛，可以吃多少天？","options":["8","6","5","10"],"answer":1,"explanation":"每天长草量=(26×8−19×15)÷(8−15)=11份，原有草量=19×15−11×15=120份；31头牛每天净消耗31−11=20份，可吃120÷20=6天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40769","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有35人，参加羽毛球赛的有26人，参加乒乓球赛的有31人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有9人，参加羽毛球和乒乓球的有12人，三项都参加的有3人。只参加其中一项比赛的有多少人？","options":["37","45","41","65"],"answer":2,"explanation":"只参加篮球=35−9−9+3=20人；同理只参加羽毛球=8人，只参加乒乓球=13人；合计20+8+13=41人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40770","module":"shuliang","prompt":"时钟8点30分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["75","85","65","105"],"answer":0,"explanation":"时针与12点方向夹角为30×8+0.5×30=255.0度，分针与12点方向夹角为6×30=180度，两针夹角为75度，取小于180度的角为75.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40771","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供12头牛吃22天，或供18头牛吃10天。若放29头牛，可以吃多少天？","options":["4","6","5","10"],"answer":2,"explanation":"每天长草量=(18×10−12×22)÷(10−22)=7份，原有草量=12×22−7×22=110份；29头牛每天净消耗29−7=22份，可吃110÷22=5天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40772","module":"shuliang","prompt":"某小组共有8名成员，现从中随机选出3名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["36","56","20","39"],"answer":0,"explanation":"从8人中选3人共C(8,3)=56种；甲、乙都不入选有C(6,3)=20种；故至少一人入选共56−20=36种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40773","module":"shuliang","prompt":"一个长方体的长、宽、高分别为3厘米、8厘米、2厘米，它的体积是多少立方厘米？","options":["13","92","48","24"],"answer":2,"explanation":"长方体体积=长×宽×高=3×8×2=48立方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40774","module":"shuliang","prompt":"某商品进价每件40元，售价每件80元时每天可卖240件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["80","94","89","90"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(240−4k)，是关于k的二次函数，当k=10时最大，此时售价=80+10=90元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40775","module":"shuliang","prompt":"快车、慢车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地51千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地69千米处。问A、B两地相距多少千米？","options":["111","141","90","153"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且快车行51千米，故第二次相遇时快车共行153千米。153大于一个全程而小于两个全程，说明快车已从B地折返，其位置距A地为2S−153（S为全程）。由2S−153=69，解得S=111千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40776","module":"shuliang","prompt":"某商品按定价出售每件可赚80元，若按定价的9折出售，每件将亏损40元。该商品的进价是多少元？","options":["1098","1169","1120","120"],"answer":2,"explanation":"设进价为C，定价为C+80；9折售价为9/10×(C+80)=C−40，解得C=1120元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40777","module":"shuliang","prompt":"一项工程，一队的工作效率是二队的5/2倍，两人合作20天完成。若由一队单独做，需要多少天完成？","options":["28","40","29","20"],"answer":0,"explanation":"设二队每天完成1份，则一队每天完成5/2份，两人合作每天7/2份，工程总量为20×7/2=70份；一队单独做需70÷5/2=28天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40778","module":"shuliang","prompt":"已知等差数列的前10项和为320，前20项和为1240，则该数列的公差是多少？","options":["5","8","6","1"],"answer":2,"explanation":"S20−2×S10=(1240)−2×(320)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40779","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供15头牛吃20天，或供22头牛吃6天。若放42头牛，可以吃多少天？","options":["2","4","6","8"],"answer":0,"explanation":"每天长草量=(22×6−15×20)÷(6−20)=12份，原有草量=15×20−12×20=60份；42头牛每天净消耗42−12=30份，可吃60÷30=2天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40781","module":"shuliang","prompt":"抽屉里有4种不同颜色的手套（每种数量都足够多），至少取出多少只才能保证有一副颜色相同的手套？","options":["4","5","7","8"],"answer":1,"explanation":"考虑最不利情形：每种颜色各取1只共4只仍无同色一副，再取1只必与某只同色，故至少取5只。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40782","module":"shuliang","prompt":"小明、小红两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地45千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地51千米处。问A、B两地相距多少千米？","options":["135","120","78","93"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且小明行45千米，故第二次相遇时小明共行135千米。135大于一个全程而小于两个全程，说明小明已从B地折返，其位置距A地为2S−135（S为全程）。由2S−135=51，解得S=93千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40783","module":"shuliang","prompt":"一个平底锅每次最多可以烙4张饼，每张饼两面都要烙，每面需要3分钟。烙5张饼最少需要多少分钟？","options":["9","30","12","11"],"answer":0,"explanation":"共需烙5×2=10面，每次最多烙4面，至少3锅次，最少3×3=9分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40784","module":"shuliang","prompt":"一项工程，王师傅先做10天、赵师傅再做4天恰好完成；若赵师傅先做10天、王师傅再做4天也恰好完成。两人合作，需要多少天完成？","options":["7","14","6","8"],"answer":0,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=14÷2=7天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40785","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供20头牛吃15天，或供28头牛吃7天。若放34头牛，可以吃多少天？","options":["8","5","4","9"],"answer":1,"explanation":"每天长草量=(28×7−20×15)÷(7−15)=13份，原有草量=20×15−13×15=105份；34头牛每天净消耗34−13=21份，可吃105÷21=5天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40786","module":"shuliang","prompt":"时钟10点40分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["80","91","71","100"],"answer":0,"explanation":"时针与12点方向夹角为30×10+0.5×40=320.0度，分针与12点方向夹角为6×40=240度，两针夹角为80度，取小于180度的角为80.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40787","module":"shuliang","prompt":"甲接水需要9分钟，乙接水需要4分钟，丙接水需要6分钟，丁接水需要8分钟，戊接水需要11分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["105","59","91","38"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按4、6、8、9、11的顺序，总等待=4×4+6×3+8×2+9×1+11×0=59分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40788","module":"shuliang","prompt":"时钟8点50分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["27","50","35","145"],"answer":2,"explanation":"时针与12点方向夹角为30×8+0.5×50=265.0度，分针与12点方向夹角为6×50=300度，两针夹角为35度，取小于180度的角为35.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40789","module":"shuliang","prompt":"一项工程，一队先做9天、二队再做15天恰好完成；若二队先做9天、一队再做15天也恰好完成。两人合作，需要多少天完成？","options":["24","12","6","13"],"answer":1,"explanation":"设一队每天完成x、二队每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=24÷2=12天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40790","module":"shuliang","prompt":"一项工程，王师傅先做18天、赵师傅再做8天恰好完成；若赵师傅先做18天、王师傅再做8天也恰好完成。两人合作，需要多少天完成？","options":["10","26","13","14"],"answer":2,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=26÷2=13天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40791","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供13头牛吃14天，或供19头牛吃7天。若放35头牛，可以吃多少天？","options":["2","5","3","6"],"answer":2,"explanation":"每天长草量=(19×7−13×14)÷(7−14)=7份，原有草量=13×14−7×14=84份；35头牛每天净消耗35−7=28份，可吃84÷28=3天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40792","module":"shuliang","prompt":"张三在李四后方147千米处，两人同时同向出发。张三每小时行80千米，李四每小时行31千米，经过多少小时张三追上李四？","options":["80","5","147","3"],"answer":3,"explanation":"每小时张三比李四多行80-31=49千米，追及时间=147÷49=3小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40793","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供11头牛吃16天，或供21头牛吃8天。若放41头牛，可以吃多少天？","options":["6","4","3","5"],"answer":1,"explanation":"每天长草量=(21×8−11×16)÷(8−16)=1份，原有草量=11×16−1×16=160份；41头牛每天净消耗41−1=40份，可吃160÷40=4天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40794","module":"shuliang","prompt":"5个正整数之和为48（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["47","48","44","43"],"answer":2,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=48−4×1=44。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40795","module":"shuliang","prompt":"某商品进价每件50元，售价每件90元时每天可卖216件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["91","88","86","90"],"answer":1,"explanation":"设售价提高k元，每天利润=(40+k)×(216−6k)，是关于k的二次函数，当k=-2时最大，此时售价=90+-2=88元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40796","module":"shuliang","prompt":"一只手表每小时比标准时间快10秒。若以标准时间为准，这只手表一昼夜（24小时）共快多少分钟？","options":["2","7","4","24"],"answer":2,"explanation":"每小时快10秒，一昼夜24小时共快24×10=240秒=4分钟。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40797","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有45人，参加数学兴趣小组的有21人，两个小组都参加的有20人。两个小组至少参加一个的共有多少人？","options":["86","66","46","24"],"answer":2,"explanation":"都参加的20人被算了两次，需减去一次，故至少参加一个的人数=45+21−20=46人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40798","module":"shuliang","prompt":"A接水需要9分钟，B接水需要3分钟，C接水需要7分钟，D接水需要6分钟，E接水需要12分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["98","53","87","37"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按3、6、7、9、12的顺序，总等待=3×4+6×3+7×2+9×1+12×0=53分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40799","module":"shuliang","prompt":"小明、小红两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地56千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地12千米处。问A、B两地相距多少千米？","options":["101","90","70","168"],"answer":1,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且小明行56千米，故第二次相遇时小明共行168千米。168大于一个全程而小于两个全程，说明小明已从B地折返，其位置距A地为2S−168（S为全程）。由2S−168=12，解得S=90千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40800","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有23人，参加物理组的有29人，参加化学组的有40人；同时参加数学和物理的有8人，参加数学和化学的有7人，参加物理和化学的有8人，三个组都参加的有3人。三个组至少参加一个的共有多少人？","options":["71","92","73","72"],"answer":3,"explanation":"由三集合容斥公式：至少参加一个=23+29+40−8−7−8+3=72人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40801","module":"shuliang","prompt":"某小组共有11名成员，现从中随机选出4名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["330","204","126","208"],"answer":1,"explanation":"从11人中选4人共C(11,4)=330种；甲、乙都不入选有C(9,4)=126种；故至少一人入选共330−126=204种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40802","module":"shuliang","prompt":"袋中有2个红球和2个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/4","1","1/2","1/3"],"answer":2,"explanation":"共有4个球，红球2个，取到红球的概率为2/4=1/2。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40803","module":"shuliang","prompt":"彩旗按“红、黄、蓝”的顺序循环排列，第26面彩旗是什么颜色？","options":["蓝","黄","红","绿"],"answer":1,"explanation":"周期为3，26÷3=8余2，第26面旗对应周期中的第2个，即“黄”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40804","module":"shuliang","prompt":"彩旗按“红、白、黑、蓝”的顺序循环排列，第62面彩旗是什么颜色？","options":["红","黑","白","蓝"],"answer":2,"explanation":"周期为4，62÷4=15余2，第62面旗对应周期中的第2个，即“白”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40805","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才4岁。”乙对甲说：“当我到你这么大时，你就43岁了。”甲今年多少岁？","options":["28","17","33","30"],"answer":3,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙4岁，即乙现在为x+d；乙到甲现在这么大时甲43岁，即甲现在为y−d。由y−d−(x+d)=d得d=(43−4)÷3=13，甲今年=43−13=30岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40806","module":"shuliang","prompt":"6个正整数之和为66（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["11","14","9","12"],"answer":0,"explanation":"最大数最小时各数尽量平均，66÷6=11余0，故最大数至少为11（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40807","module":"shuliang","prompt":"今天是星期六，再过63天是星期几？","options":["星期五","星期日","星期六","星期三"],"answer":2,"explanation":"63÷7=9余0，星期六往后推0天是星期六。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40808","module":"shuliang","prompt":"今年甲的年龄是乙的3倍，6年后甲的年龄是乙的2倍。乙今年多少岁？","options":["4","9","6","36"],"answer":2,"explanation":"设乙今年x岁，则甲为3x岁；6年后：3x+6=2(x+6)，解得x=6岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40809","module":"shuliang","prompt":"4个正整数之和为53（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["49","53","51","50"],"answer":3,"explanation":"要使最大的数最大，其余3个数都取最小值1，故最大数=53−3×1=50。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40810","module":"shuliang","prompt":"今年甲的年龄是乙的3倍，13年后甲的年龄是乙的2倍。乙今年多少岁？","options":["169","15","11","13"],"answer":3,"explanation":"设乙今年x岁，则甲为3x岁；13年后：3x+13=2(x+13)，解得x=13岁。","exam":"通用基础","__sub":"年龄问题","diff":2},{"id":"sl-40811","module":"shuliang","prompt":"一项工程，师傅甲的工作效率是师傅乙的3/2倍，两人合作21天完成。若由师傅甲单独做，需要多少天完成？","options":["35","42","37","21"],"answer":0,"explanation":"设师傅乙每天完成1份，则师傅甲每天完成3/2份，两人合作每天5/2份，工程总量为21×5/2=105/2份；师傅甲单独做需105/2÷3/2=35天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40812","module":"shuliang","prompt":"已知等差数列的前10项和为205，前20项和为710，则该数列的公差是多少？","options":["3","5","2","1"],"answer":0,"explanation":"S20−2×S10=(710)−2×(205)=300=100d（第11到20项之和比前10项之和多100d），故d=3。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40813","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖104件。售价每提高1元，每天少卖2件。要使每天利润最大，售价应定为每件多少元？","options":["71","75","70","60"],"answer":0,"explanation":"设售价提高k元，每天利润=(30+k)×(104−2k)，是关于k的二次函数，当k=11时最大，此时售价=60+11=71元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40814","module":"shuliang","prompt":"某商品进价700元，售价1274元。该商品的利润率是多少？","options":["89%","82%","78%","164%"],"answer":1,"explanation":"利润=1274−700=574元，利润率=574÷700×100%=82%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40815","module":"shuliang","prompt":"6个正整数之和为38（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","7","6","8"],"answer":1,"explanation":"最大数最小时各数尽量平均，38÷6=6余2，故最大数至少为7（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40816","module":"shuliang","prompt":"一列火车长149米，以每秒38米的速度通过一座长3002米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["82","3","79","85"],"answer":0,"explanation":"火车完全过桥需行驶149+3002=3151米，时间=3151÷38=82秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40817","module":"shuliang","prompt":"今年父子二人年龄之和是90岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["74","18","72","69"],"answer":2,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=90÷5=18岁，父亲=4×18=72岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40818","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供16头牛吃15天，或供32头牛吃7天。若放44头牛，可以吃多少天？","options":["7","6","4","5"],"answer":3,"explanation":"每天长草量=(32×7−16×15)÷(7−15)=2份，原有草量=16×15−2×15=210份；44头牛每天净消耗44−2=42份，可吃210÷42=5天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40819","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供19头牛吃20天，或供25头牛吃10天。若放28头牛，可以吃多少天？","options":["8","11","7","14"],"answer":0,"explanation":"每天长草量=(25×10−19×20)÷(10−20)=13份，原有草量=19×20−13×20=120份；28头牛每天净消耗28−13=15份，可吃120÷15=8天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40820","module":"shuliang","prompt":"两个正数的和为24，要使它们的乘积最大，则最大的乘积是多少？","options":["141","24","145","144"],"answer":3,"explanation":"两数和一定时，两数相等时乘积最大，均为24÷2=12，最大乘积=12×12=144。","exam":"通用基础","__sub":"最值问题","diff":2},{"id":"sl-40821","module":"shuliang","prompt":"某商品进价每件30元，售价每件50元时每天可卖252件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["60","62","61","50"],"answer":2,"explanation":"设售价提高k元，每天利润=(20+k)×(252−6k)，是关于k的二次函数，当k=11时最大，此时售价=50+11=61元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40822","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行48千米，按原路返回时每小时行24千米。该车往返全程的平均速度是多少千米/小时？","options":["33","36","32","31"],"answer":2,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/48+1/24)=2×48×24÷(48+24)=32千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40823","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有33人，参加羽毛球赛的有27人，参加乒乓球赛的有27人；同时参加篮球和羽毛球的有8人，参加篮球和乒乓球的有6人，参加羽毛球和乒乓球的有6人，三项都参加的有2人。只参加其中一项比赛的有多少人？","options":["57","53","52","69"],"answer":1,"explanation":"只参加篮球=33−8−6+2=21人；同理只参加羽毛球=15人，只参加乒乓球=17人；合计21+15+17=53人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40824","module":"shuliang","prompt":"某淘汰赛共有13支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["12","13","6","15"],"answer":0,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰12支，故共需12场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40825","module":"shuliang","prompt":"甲接水需要9分钟，乙接水需要8分钟，丙接水需要2分钟，丁接水需要4分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["53","22","39","23"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按2、4、8、9的顺序，总等待=2×3+4×2+8×1+9×0=22分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40826","module":"shuliang","prompt":"袋中有5个红球和7个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["5/12","7/12","1","1/2"],"answer":0,"explanation":"共有12个球，红球5个，取到红球的概率为5/12。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40827","module":"shuliang","prompt":"一个圆的半径为30厘米（π取3.14），它的面积是多少平方厘米？","options":["2792","188","2870","2826"],"answer":3,"explanation":"圆的面积=πr²=3.14×30×30=2826平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40828","module":"shuliang","prompt":"甲数是乙数的4倍，两数之和是120。乙数是多少？","options":["96","24","31","21"],"answer":1,"explanation":"乙数为1份，甲数为4份，共5份；乙数=120÷5=24。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40829","module":"shuliang","prompt":"一片牧场，草每天匀速生长。这片草场可供19头牛吃20天，或供28头牛吃10天。若放30头牛，可以吃多少天？","options":["13","12","8","9"],"answer":3,"explanation":"每天长草量=(28×10−19×20)÷(10−20)=10份，原有草量=19×20−10×20=180份；30头牛每天净消耗30−10=20份，可吃180÷20=9天。","exam":"通用基础","__sub":"牛吃草问题","diff":3},{"id":"sl-40830","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油11升；乙种卡车每次可运3吨货物，耗油7升。现要运送42吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["70","66","60","98"],"answer":1,"explanation":"甲车每吨耗油11/7升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：6车次运42吨，余0吨用乙车0次，共耗油66升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40831","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有41人，参加数学兴趣小组的有25人，两个小组都参加的有14人。两个小组至少参加一个的共有多少人？","options":["66","52","80","16"],"answer":1,"explanation":"都参加的14人被算了两次，需减去一次，故至少参加一个的人数=41+25−14=52人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40832","module":"shuliang","prompt":"某商场促销“满100减10”，小明购买了标价300元的商品（满足优惠条件）。实际付款相当于打几折？","options":["1折","10折","8折","9折"],"answer":3,"explanation":"优惠后实付300−3×10=270元，270÷300=9/10，相当于打9折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40833","module":"shuliang","prompt":"某小组共有12名成员，现从中随机选出3名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["102","220","120","100"],"answer":3,"explanation":"从12人中选3人共C(12,3)=220种；甲、乙都不入选有C(10,3)=120种；故至少一人入选共220−120=100种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40834","module":"shuliang","prompt":"某商品进价900元，售价1323元。该商品的利润率是多少？","options":["94%","52%","44%","47%"],"answer":3,"explanation":"利润=1323−900=423元，利润率=423÷900×100%=47%。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40835","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有35人，参加羽毛球赛的有22人，参加乒乓球赛的有27人；同时参加篮球和羽毛球的有10人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有8人，三项都参加的有2人。只参加其中一项比赛的有多少人？","options":["34","38","32","58"],"answer":0,"explanation":"只参加篮球=35−10−10+2=17人；同理只参加羽毛球=6人，只参加乒乓球=11人；合计17+6+11=34人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40836","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有36人，参加数学兴趣小组的有29人，两个小组都参加的有23人。两个小组至少参加一个的共有多少人？","options":["88","65","42","7"],"answer":2,"explanation":"都参加的23人被算了两次，需减去一次，故至少参加一个的人数=36+29−23=42人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40837","module":"shuliang","prompt":"已知等差数列的首项为2，公差为6，则它的前18项之和是多少？","options":["1872","954","961","949"],"answer":1,"explanation":"第18项=2+(18-1)×6=104，前18项和=n×(首项+末项)÷2=18×(2+104)÷2=954。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40838","module":"shuliang","prompt":"一个平底锅每次最多可以烙3张饼，每张饼两面都要烙，每面需要4分钟。烙6张饼最少需要多少分钟？","options":["48","16","19","14"],"answer":1,"explanation":"共需烙6×2=12面，每次最多烙3面，至少4锅次，最少4×4=16分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40839","module":"shuliang","prompt":"一个长方体的长、宽、高分别为8厘米、7厘米、12厘米，它的表面积是多少平方厘米？","options":["54","672","27","472"],"answer":3,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(56+84+96)=472平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40840","module":"shuliang","prompt":"一列火车长228米，以每秒22米的速度通过一座长2288米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["115","10","104","114"],"answer":3,"explanation":"火车完全过桥需行驶228+2288=2516米，时间=2516÷22=114秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40841","module":"shuliang","prompt":"甲接水需要7分钟，乙接水需要9分钟，丙接水需要8分钟，丁接水需要6分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["30","76","64","40"],"answer":3,"explanation":"让用时短的人先接水可使总等待时间最短。按6、7、8、9的顺序，总等待=6×3+7×2+8×1+9×0=40分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40842","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才20岁。”乙对甲说：“当我到你这么大时，你就50岁了。”甲今年多少岁？","options":["43","30","40","38"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙20岁，即乙现在为x+d；乙到甲现在这么大时甲50岁，即甲现在为y−d。由y−d−(x+d)=d得d=(50−20)÷3=10，甲今年=50−10=40岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40843","module":"shuliang","prompt":"一项工程，张师傅先做10天、李师傅再做12天恰好完成；若李师傅先做10天、张师傅再做12天也恰好完成。两人合作，需要多少天完成？","options":["22","11","2","12"],"answer":1,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=22÷2=11天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40844","module":"shuliang","prompt":"某小组共有10名成员，现从中随机选出5名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["201","252","56","196"],"answer":3,"explanation":"从10人中选5人共C(10,5)=252种；甲、乙都不入选有C(8,5)=56种；故至少一人入选共252−56=196种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40845","module":"shuliang","prompt":"一只手表每小时比标准时间快15秒。若以标准时间为准，这只手表一昼夜（24小时）共快多少分钟？","options":["7","6","5","24"],"answer":1,"explanation":"每小时快15秒，一昼夜24小时共快24×15=360秒=6分钟。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40846","module":"shuliang","prompt":"5个正整数之和为47（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["46","47","43","42"],"answer":2,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=47−4×1=43。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40847","module":"shuliang","prompt":"今年父子二人年龄之和是75岁，父亲年龄是儿子年龄的4倍。父亲今年多少岁？","options":["60","15","64","55"],"answer":0,"explanation":"儿子年龄为1份，父亲为4份，共5份；儿子=75÷5=15岁，父亲=4×15=60岁。","exam":"通用基础","__sub":"年龄问题","diff":1},{"id":"sl-40848","module":"shuliang","prompt":"一个平底锅每次最多可以烙4张饼，每张饼两面都要烙，每面需要2分钟。烙4张饼最少需要多少分钟？","options":["3","16","6","4"],"answer":3,"explanation":"共需烙4×2=8面，每次最多烙4面，至少2锅次，最少2×2=4分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40849","module":"shuliang","prompt":"一项工程，一队单独做需要6天完成，二队单独做需要3天完成。两人（队）合作，需要多少天完成？","options":["2","9","3","5"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/6+1/3=(6+3)/18，合作需要18÷(6+3)=2天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40850","module":"shuliang","prompt":"某商品进价每件40元，售价每件80元时每天可卖90件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["80","77","74","75"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(90−3k)，是关于k的二次函数，当k=-5时最大，此时售价=80+-5=75元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40851","module":"shuliang","prompt":"5个正整数之和为37（每个数至少为1），要使其中最大的数尽可能大，则这个最大的数最大是多少？","options":["37","33","34","32"],"answer":1,"explanation":"要使最大的数最大，其余4个数都取最小值1，故最大数=37−4×1=33。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40852","module":"shuliang","prompt":"某单位组织124人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1293","1200","1062","1400"],"answer":1,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1200元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40853","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有33人，参加物理组的有27人，参加化学组的有32人；同时参加数学和物理的有11人，参加数学和化学的有7人，参加物理和化学的有8人，三个组都参加的有5人。三个组至少参加一个的共有多少人？","options":["92","71","75","67"],"answer":1,"explanation":"由三集合容斥公式：至少参加一个=33+27+32−11−7−8+5=71人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40854","module":"shuliang","prompt":"一项工程，师傅甲先做19天、师傅乙再做11天恰好完成；若师傅乙先做19天、师傅甲再做11天也恰好完成。两人合作，需要多少天完成？","options":["30","15","8","16"],"answer":1,"explanation":"设师傅甲每天完成x、师傅乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=30÷2=15天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40855","module":"shuliang","prompt":"时钟11点50分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["55","70","46","125"],"answer":0,"explanation":"时针与12点方向夹角为30×11+0.5×50=355.0度，分针与12点方向夹角为6×50=300度，两针夹角为55度，取小于180度的角为55.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40856","module":"shuliang","prompt":"甲种卡车每次可运8吨货物，耗油10升；乙种卡车每次可运2吨货物，耗油7升。现要运送96吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["123","120","114","336"],"answer":1,"explanation":"甲车每吨耗油10/8升，乙车每吨耗油7/2升，甲车更省。尽量用甲车：12车次运96吨，余0吨用乙车0次，共耗油120升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40857","module":"shuliang","prompt":"某淘汰赛共有29支队伍参加，采用单场淘汰制（每场比赛淘汰一队，无平局），最终决出冠军。一共需要进行多少场比赛？","options":["31","29","14","28"],"answer":3,"explanation":"每场比赛淘汰1支队伍，决出冠军需淘汰28支，故共需28场比赛。","exam":"通用基础","__sub":"排列组合","diff":1},{"id":"sl-40858","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有43人，参加数学兴趣小组的有16人，两个小组都参加的有5人。两个小组至少参加一个的共有多少人？","options":["54","59","64","27"],"answer":0,"explanation":"都参加的5人被算了两次，需减去一次，故至少参加一个的人数=43+16−5=54人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40859","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖324件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["72","75","69","60"],"answer":0,"explanation":"设售价提高k元，每天利润=(30+k)×(324−6k)，是关于k的二次函数，当k=12时最大，此时售价=60+12=72元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40860","module":"shuliang","prompt":"一列火车长296米，以每秒15米的速度通过一座长1485米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["121","19","99","118"],"answer":3,"explanation":"火车完全过桥需行驶296+1485=1781米，时间=1781÷15=118秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40861","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第34面彩旗是什么颜色？","options":["甲","戊","丙","丁"],"answer":3,"explanation":"周期为5，34÷5=6余4，第34面旗对应周期中的第4个，即“丁”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40862","module":"shuliang","prompt":"甲数是乙数的2倍，两数之和是114。乙数是多少？","options":["38","76","41","36"],"answer":0,"explanation":"乙数为1份，甲数为2份，共3份；乙数=114÷3=38。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40863","module":"shuliang","prompt":"一项工程，甲的工作效率是乙的5/2倍，两人合作30天完成。若由甲单独做，需要多少天完成？","options":["42","60","45","30"],"answer":0,"explanation":"设乙每天完成1份，则甲每天完成5/2份，两人合作每天7/2份，工程总量为30×7/2=105份；甲单独做需105÷5/2=42天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40864","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是15立方分米。圆锥的体积是多少立方分米？","options":["15","5","7","30"],"answer":1,"explanation":"等底等高的圆锥体积是圆柱的1/3，即15÷3=5立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40865","module":"shuliang","prompt":"一个平底锅每次最多可以烙4张饼，每张饼两面都要烙，每面需要2分钟。烙6张饼最少需要多少分钟？","options":["8","24","6","9"],"answer":2,"explanation":"共需烙6×2=12面，每次最多烙4面，至少3锅次，最少3×2=6分钟。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40866","module":"shuliang","prompt":"时钟12点40分时，时针与分针的夹角（取小于180度的角）是多少度？","options":["140","145","133","40"],"answer":0,"explanation":"时针与12点方向夹角为30×12+0.5×40=380.0度，分针与12点方向夹角为6×40=240度，两针夹角为140度，取小于180度的角为140.0度。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40867","module":"shuliang","prompt":"快车和慢车的速度比为7:2，两人同时同地同向出发赛跑，当快车到达终点时，慢车距终点还有30米。赛道全程是多少米？","options":["42","92","16","210"],"answer":0,"explanation":"同一时间内路程比等于速度比，慢车走了全程的2/7，还差全程的5/7=30米，故全程=30×7÷5=42米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40868","module":"shuliang","prompt":"一项工程，张师傅先做10天、李师傅再做8天恰好完成；若李师傅先做10天、张师傅再做8天也恰好完成。两人合作，需要多少天完成？","options":["10","18","2","9"],"answer":3,"explanation":"设张师傅每天完成x、李师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=18÷2=9天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40869","module":"shuliang","prompt":"一项工程，王师傅的工作效率是赵师傅的5/2倍，两人合作15天完成。若由王师傅单独做，需要多少天完成？","options":["15","30","23","21"],"answer":3,"explanation":"设赵师傅每天完成1份，则王师傅每天完成5/2份，两人合作每天7/2份，工程总量为15×7/2=105/2份；王师傅单独做需105/2÷5/2=21天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40870","module":"shuliang","prompt":"某商场促销“满200减60”，小明购买了标价600元的商品（满足优惠条件）。实际付款相当于打几折？","options":["6折","8折","7折","3折"],"answer":2,"explanation":"优惠后实付600−3×60=420元，420÷600=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40871","module":"shuliang","prompt":"一项工程，王师傅先做11天、赵师傅再做17天恰好完成；若赵师傅先做11天、王师傅再做17天也恰好完成。两人合作，需要多少天完成？","options":["15","28","6","14"],"answer":3,"explanation":"设王师傅每天完成x、赵师傅每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=28÷2=14天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40872","module":"shuliang","prompt":"6个正整数之和为70（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["10","13","12","11"],"answer":2,"explanation":"最大数最小时各数尽量平均，70÷6=11余4，故最大数至少为12（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40873","module":"shuliang","prompt":"甲种卡车每次可运5吨货物，耗油9升；乙种卡车每次可运3吨货物，耗油7升。现要运送25吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["39","51","45","56"],"answer":2,"explanation":"甲车每吨耗油9/5升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：5车次运25吨，余0吨用乙车0次，共耗油45升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40874","module":"shuliang","prompt":"某商场促销“满100减30”，小明购买了标价300元的商品（满足优惠条件）。实际付款相当于打几折？","options":["6折","8折","7折","3折"],"answer":2,"explanation":"优惠后实付300−3×30=210元，210÷300=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40875","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需75小时，逆流需93小时，两码头相距2325千米。该轮船在静水中的速度是多少千米/小时？","options":["3","28","31","27"],"answer":1,"explanation":"顺流速度=2325÷75=31千米/小时，逆流速度=2325÷93=25千米/小时；静水速度=(31+25)÷2=28千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40876","module":"shuliang","prompt":"今天是星期日，再过36天是星期几？","options":["星期一","星期二","星期日","星期六"],"answer":0,"explanation":"36÷7=5余1，星期日往后推1天是星期一。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40877","module":"shuliang","prompt":"某商品按进价加价60%定价，然后按9折出售，仍可获利。该商品的利润率是多少？","options":["49%","54%","44%","42%"],"answer":2,"explanation":"设进价为100，售价=100×(1+60%)×9/10=144，利润率=144−100=44%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40878","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有29人，参加羽毛球赛的有27人，参加乒乓球赛的有27人；同时参加篮球和羽毛球的有9人，参加篮球和乒乓球的有7人，参加羽毛球和乒乓球的有11人，三项都参加的有6人。只参加其中一项比赛的有多少人？","options":["45","49","47","62"],"answer":2,"explanation":"只参加篮球=29−9−7+6=19人；同理只参加羽毛球=13人，只参加乒乓球=15人；合计19+13+15=47人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40879","module":"shuliang","prompt":"某商品按进价加价70%定价，然后按8折出售，仍可获利。该商品的利润率是多少？","options":["44%","56%","36%","33%"],"answer":2,"explanation":"设进价为100，售价=100×(1+70%)×8/10=136，利润率=136−100=36%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40880","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才5岁。”乙对甲说：“当我到你这么大时，你就26岁了。”甲今年多少岁？","options":["12","19","20","18"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙5岁，即乙现在为x+d；乙到甲现在这么大时甲26岁，即甲现在为y−d。由y−d−(x+d)=d得d=(26−5)÷3=7，甲今年=26−7=19岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40881","module":"shuliang","prompt":"某年级组织课外活动，参加数学组的有38人，参加物理组的有23人，参加化学组的有37人；同时参加数学和物理的有9人，参加数学和化学的有8人，参加物理和化学的有8人，三个组都参加的有4人。三个组至少参加一个的共有多少人？","options":["76","98","80","77"],"answer":3,"explanation":"由三集合容斥公式：至少参加一个=38+23+37−9−8−8+4=77人。","exam":"通用基础","__sub":"容斥原理","diff":2},{"id":"sl-40882","module":"shuliang","prompt":"同时掷两枚均匀的骰子，点数之和为8的概率是多少？","options":["1/12","1/9","1/6","5/36"],"answer":3,"explanation":"两枚骰子共6×6=36种等可能结果，点数之和为8的有5种，概率为5/36。","exam":"通用基础","__sub":"概率问题","diff":2},{"id":"sl-40883","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有33人，参加羽毛球赛的有20人，参加乒乓球赛的有30人；同时参加篮球和羽毛球的有10人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有12人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["31","35","30","55"],"answer":0,"explanation":"只参加篮球=33−10−10+4=17人；同理只参加羽毛球=2人，只参加乒乓球=12人；合计17+2+12=31人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40884","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖90件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["63","60","59","45"],"answer":1,"explanation":"设售价提高k元，每天利润=(30+k)×(90−3k)，是关于k的二次函数，当k=0时最大，此时售价=60+0=60元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40885","module":"shuliang","prompt":"A接水需要5分钟，B接水需要7分钟，C接水需要4分钟，D接水需要9分钟，E接水需要3分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["64","76","41","28"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按3、4、5、7、9的顺序，总等待=3×4+4×3+5×2+7×1+9×0=41分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40886","module":"shuliang","prompt":"彩旗按“红、白、黑、蓝”的顺序循环排列，第32面彩旗是什么颜色？","options":["黑","红","蓝","白"],"answer":2,"explanation":"周期为4，32÷4=8余0，第32面旗对应周期中的第4个，即“蓝”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40887","module":"shuliang","prompt":"甲数是乙数的4倍，两数之和是240。乙数是多少？","options":["48","192","55","47"],"answer":0,"explanation":"乙数为1份，甲数为4份，共5份；乙数=240÷5=48。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40888","module":"shuliang","prompt":"一列火车长190米，以每秒26米的速度通过一座长2106米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["88","7","81","90"],"answer":0,"explanation":"火车完全过桥需行驶190+2106=2296米，时间=2296÷26=88秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40889","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才4岁。”乙对甲说：“当我到你这么大时，你就10岁了。”甲今年多少岁？","options":["6","8","11","7"],"answer":1,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙4岁，即乙现在为x+d；乙到甲现在这么大时甲10岁，即甲现在为y−d。由y−d−(x+d)=d得d=(10−4)÷3=2，甲今年=10−2=8岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40890","module":"shuliang","prompt":"一项工程，一队的工作效率是二队的3/2倍，两人合作12天完成。若由一队单独做，需要多少天完成？","options":["12","24","22","20"],"answer":3,"explanation":"设二队每天完成1份，则一队每天完成3/2份，两人合作每天5/2份，工程总量为12×5/2=30份；一队单独做需30÷3/2=20天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40891","module":"shuliang","prompt":"某小组共有12名成员，现从中随机选出4名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["495","285","210","290"],"answer":1,"explanation":"从12人中选4人共C(12,4)=495种；甲、乙都不入选有C(10,4)=210种；故至少一人入选共495−210=285种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40892","module":"shuliang","prompt":"甲接水需要4分钟，乙接水需要6分钟，丙接水需要9分钟，丁接水需要3分钟，戊接水需要11分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["81","45","73","33"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按3、4、6、9、11的顺序，总等待=3×4+4×3+6×2+9×1+11×0=45分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40893","module":"shuliang","prompt":"把228个名额按8:7:4的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["48","96","180","132"],"answer":1,"explanation":"总份数=8+7+4=19，每份228÷19=12个，最多的班级分得8×12=96个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40894","module":"shuliang","prompt":"小明和小红的速度比为5:4，两人同时同地同向出发赛跑，当小明到达终点时，小红距终点还有50米。赛道全程是多少米？","options":["250","286","240","50"],"answer":0,"explanation":"同一时间内路程比等于速度比，小红走了全程的4/5，还差全程的1/5=50米，故全程=50×5÷1=250米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40895","module":"shuliang","prompt":"一个长方形的长为11米，宽为24米，它的周长是多少米？","options":["264","70","35","72"],"answer":1,"explanation":"长方形周长=2×（长+宽）=2×(11+24)=70米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40896","module":"shuliang","prompt":"已知等差数列的前10项和为230，前20项和为860，则该数列的公差是多少？","options":["3","5","4","1"],"answer":2,"explanation":"S20−2×S10=(860)−2×(230)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40897","module":"shuliang","prompt":"张三和李四分别从相距408千米的两地同时出发，相向而行。张三每小时行58千米，李四每小时行44千米，经过多少小时两车相遇？","options":["5","4","3","58"],"answer":1,"explanation":"两车速度之和为58+44=102千米/小时，相遇时间=408÷102=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40898","module":"shuliang","prompt":"A接水需要4分钟，B接水需要9分钟，C接水需要8分钟，D接水需要12分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["65","78","37","33"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按4、8、9、12的顺序，总等待=4×3+8×2+9×1+12×0=37分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40899","module":"shuliang","prompt":"同一时刻，一根5米高的标杆在阳光下的影长为3米，附近一棵大树的影长为12米。这棵大树的高度是多少米？","options":["12","17","21","20"],"answer":3,"explanation":"同一时刻物高与影长成正比，树高=5×12÷3=20米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40900","module":"shuliang","prompt":"甲接水需要8分钟，乙接水需要5分钟，丙接水需要3分钟，丁接水需要9分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["49","55","27","25"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按3、5、8、9的顺序，总等待=3×3+5×2+8×1+9×0=27分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40901","module":"shuliang","prompt":"已知等差数列的首项为7，公差为3，则它的前10项之和是多少？","options":["200","340","212","205"],"answer":3,"explanation":"第10项=7+(10-1)×3=34，前10项和=n×(首项+末项)÷2=10×(7+34)÷2=205。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40902","module":"shuliang","prompt":"甲数是乙数的2倍，两数之和是57。乙数是多少？","options":["19","38","27","18"],"answer":0,"explanation":"乙数为1份，甲数为2份，共3份；乙数=57÷3=19。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40903","module":"shuliang","prompt":"今天是星期六，再过138天是星期几？","options":["星期三","星期五","星期四","星期一"],"answer":2,"explanation":"138÷7=19余5，星期六往后推5天是星期四。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40904","module":"shuliang","prompt":"已知等差数列的前10项和为220，前20项和为840，则该数列的公差是多少？","options":["6","4","3","1"],"answer":1,"explanation":"S20−2×S10=(840)−2×(220)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40905","module":"shuliang","prompt":"一个长方体的长、宽、高分别为5厘米、2厘米、5厘米，它的表面积是多少平方厘米？","options":["24","50","12","90"],"answer":3,"explanation":"长方体表面积=2×（长×宽+宽×高+长×高）=2×(10+10+25)=90平方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40906","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行66千米，按原路返回时每小时行33千米。该车往返全程的平均速度是多少千米/小时？","options":["49","44","45","43"],"answer":1,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/66+1/33)=2×66×33÷(66+33)=44千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40907","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才14岁。”乙对甲说：“当我到你这么大时，你就50岁了。”甲今年多少岁？","options":["38","26","40","36"],"answer":0,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙14岁，即乙现在为x+d；乙到甲现在这么大时甲50岁，即甲现在为y−d。由y−d−(x+d)=d得d=(50−14)÷3=12，甲今年=50−12=38岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40908","module":"shuliang","prompt":"某单位组织94人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["960","1086","876","1200"],"answer":0,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为960元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40909","module":"shuliang","prompt":"5个正整数之和为38（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["7","11","8","9"],"answer":2,"explanation":"最大数最小时各数尽量平均，38÷5=7余3，故最大数至少为8（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40910","module":"shuliang","prompt":"已知等比数列的首项为2，公比为3，则它的第7项是多少？","options":["486","4374","1458","1461"],"answer":2,"explanation":"等比数列第n项=首项×公比^(n−1)=2×3^(7-1)=1458。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40911","module":"shuliang","prompt":"今天是星期日，再过108天是星期几？","options":["星期四","星期三","星期二","星期六"],"answer":1,"explanation":"108÷7=15余3，星期日往后推3天是星期三。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40912","module":"shuliang","prompt":"某商品进价每件50元，售价每件90元时每天可卖120件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["90","89","83","85"],"answer":3,"explanation":"设售价提高k元，每天利润=(40+k)×(120−4k)，是关于k的二次函数，当k=-5时最大，此时售价=90+-5=85元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40913","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有41人，参加数学兴趣小组的有19人，两个小组都参加的有17人。两个小组至少参加一个的共有多少人？","options":["22","60","77","43"],"answer":3,"explanation":"都参加的17人被算了两次，需减去一次，故至少参加一个的人数=41+19−17=43人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40914","module":"shuliang","prompt":"一项工程，师傅甲先做11天、师傅乙再做13天恰好完成；若师傅乙先做11天、师傅甲再做13天也恰好完成。两人合作，需要多少天完成？","options":["2","24","12","13"],"answer":2,"explanation":"设师傅甲每天完成x、师傅乙每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=24÷2=12天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40915","module":"shuliang","prompt":"甲数是乙数的5倍，两数之和是144。乙数是多少？","options":["19","120","32","24"],"answer":3,"explanation":"乙数为1份，甲数为5份，共6份；乙数=144÷6=24。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40916","module":"shuliang","prompt":"一昼夜（24小时）内，时钟的时针与分针共重合多少次？","options":["23","24","22","12"],"answer":2,"explanation":"分针每小时追上时针一次（重合一次），但0点到1点与11点到12点之间的重合合为12点整同一次，故12小时重合11次，一昼夜共22次。","exam":"通用基础","__sub":"钟表问题","diff":2},{"id":"sl-40917","module":"shuliang","prompt":"某小组共有9名成员，现从中随机选出3名参加活动。若甲、乙两人至少有一人入选，共有多少种选法？","options":["49","84","35","50"],"answer":0,"explanation":"从9人中选3人共C(9,3)=84种；甲、乙都不入选有C(7,3)=35种；故至少一人入选共84−35=49种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40918","module":"shuliang","prompt":"同一时刻，一根3米高的标杆在阳光下的影长为9米，附近一棵大树的影长为18米。这棵大树的高度是多少米？","options":["18","21","7","6"],"answer":3,"explanation":"同一时刻物高与影长成正比，树高=3×18÷9=6米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40919","module":"shuliang","prompt":"一项工程，一队单独做需要12天完成，二队单独做需要24天完成。现两人合作4天后，剩余部分由二队单独完成，还需要多少天？","options":["14","20","12","24"],"answer":2,"explanation":"两人每天合作完成1/12+1/24=(12+24)/288，4天完成144/288，剩144/288；二队每天完成1/24，还需24×144/288=12天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40920","module":"shuliang","prompt":"客车、货车两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地51千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地9千米处。问A、B两地相距多少千米？","options":["58","91","81","153"],"answer":2,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且客车行51千米，故第二次相遇时客车共行153千米。153大于一个全程而小于两个全程，说明客车已从B地折返，其位置距A地为2S−153（S为全程）。由2S−153=9，解得S=81千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40921","module":"shuliang","prompt":"一项工程，一队单独做需要24天完成，二队单独做需要8天完成。两人（队）合作，需要多少天完成？","options":["32","6","16","7"],"answer":1,"explanation":"把工程总量看作1，两人效率之和为1/24+1/8=(24+8)/192，合作需要192÷(24+8)=6天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40922","module":"shuliang","prompt":"已知等差数列的前10项和为310，前20项和为1220，则该数列的公差是多少？","options":["5","7","6","1"],"answer":2,"explanation":"S20−2×S10=(1220)−2×(310)=600=100d（第11到20项之和比前10项之和多100d），故d=6。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40923","module":"shuliang","prompt":"一项工程，王师傅的工作效率是赵师傅的2倍，两人合作20天完成。若由王师傅单独做，需要多少天完成？","options":["30","20","31","28"],"answer":0,"explanation":"设赵师傅每天完成1份，则王师傅每天完成2份，两人合作每天3份，工程总量为20×3=60份；王师傅单独做需60÷2=30天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40924","module":"shuliang","prompt":"同一时刻，一根3米高的标杆在阳光下的影长为3米，附近一棵大树的影长为6米。这棵大树的高度是多少米？","options":["9","6","7","18"],"answer":1,"explanation":"同一时刻物高与影长成正比，树高=3×6÷3=6米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40925","module":"shuliang","prompt":"同一时刻，一根2米高的标杆在阳光下的影长为3米，附近一棵大树的影长为15米。这棵大树的高度是多少米？","options":["11","17","10","15"],"answer":2,"explanation":"同一时刻物高与影长成正比，树高=2×15÷3=10米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40926","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有22人，参加羽毛球赛的有30人，参加乒乓球赛的有24人；同时参加篮球和羽毛球的有12人，参加篮球和乒乓球的有12人，参加羽毛球和乒乓球的有12人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["44","19","14","16"],"answer":3,"explanation":"只参加篮球=22−12−12+4=2人；同理只参加羽毛球=10人，只参加乒乓球=4人；合计2+10+4=16人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40927","module":"shuliang","prompt":"6名选手排成一排合影留念，其中甲、乙两人必须相邻，共有多少种不同的排法？","options":["240","720","120","480"],"answer":0,"explanation":"把甲、乙捆绑成一个整体，与其余4人共5个元素全排列，有(5)!=120种；甲、乙内部可交换有2种；共2×120=240种。","exam":"通用基础","__sub":"排列组合","diff":2},{"id":"sl-40929","module":"shuliang","prompt":"一个长方形的长为24米，宽为13米，它的周长是多少米？","options":["312","74","37","76"],"answer":1,"explanation":"长方形周长=2×（长+宽）=2×(24+13)=74米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40930","module":"shuliang","prompt":"A接水需要8分钟，B接水需要12分钟，C接水需要10分钟，D接水需要5分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["41","84","74","35"],"answer":0,"explanation":"让用时短的人先接水可使总等待时间最短。按5、8、10、12的顺序，总等待=5×3+8×2+10×1+12×0=41分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40931","module":"shuliang","prompt":"5个正整数之和为74（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["15","18","13","14"],"answer":0,"explanation":"最大数最小时各数尽量平均，74÷5=14余4，故最大数至少为15（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40932","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是51立方分米。圆锥的体积是多少立方分米？","options":["51","17","25","102"],"answer":1,"explanation":"等底等高的圆锥体积是圆柱的1/3，即51÷3=17立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40933","module":"shuliang","prompt":"甲和乙分别从相距545千米的两地同时出发，相向而行。甲每小时行66千米，乙每小时行43千米，经过多少小时两车相遇？","options":["5","7","4","6"],"answer":0,"explanation":"两车速度之和为66+43=109千米/小时，相遇时间=545÷109=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40934","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有27人，参加羽毛球赛的有28人，参加乒乓球赛的有28人；同时参加篮球和羽毛球的有8人，参加篮球和乒乓球的有11人，参加羽毛球和乒乓球的有12人，三项都参加的有5人。只参加其中一项比赛的有多少人？","options":["36","39","32","57"],"answer":0,"explanation":"只参加篮球=27−8−11+5=13人；同理只参加羽毛球=13人，只参加乒乓球=10人；合计13+13+10=36人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40935","module":"shuliang","prompt":"已知等差数列的前10项和为200，前20项和为800，则该数列的公差是多少？","options":["6","4","3","1"],"answer":1,"explanation":"S20−2×S10=(800)−2×(200)=400=100d（第11到20项之和比前10项之和多100d），故d=4。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40936","module":"shuliang","prompt":"4个正整数之和为29（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["9","8","6","7"],"answer":1,"explanation":"最大数最小时各数尽量平均，29÷4=7余1，故最大数至少为8（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40937","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需69小时，逆流需99小时，两码头相距2277千米。该轮船在静水中的速度是多少千米/小时？","options":["33","5","28","26"],"answer":2,"explanation":"顺流速度=2277÷69=33千米/小时，逆流速度=2277÷99=23千米/小时；静水速度=(33+23)÷2=28千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40938","module":"shuliang","prompt":"一个长方体的长、宽、高分别为2厘米、6厘米、11厘米，它的体积是多少立方厘米？","options":["19","200","132","12"],"answer":2,"explanation":"长方体体积=长×宽×高=2×6×11=132立方厘米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40939","module":"shuliang","prompt":"某商品按进价加价60%定价，然后按8折出售，仍可获利。该商品的利润率是多少？","options":["28%","48%","32%","27%"],"answer":0,"explanation":"设进价为100，售价=100×(1+60%)×8/10=128，利润率=128−100=28%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40940","module":"shuliang","prompt":"一项工程，师傅甲单独做需要10天完成，师傅乙单独做需要15天完成。两人（队）合作，需要多少天完成？","options":["6","25","5","13"],"answer":0,"explanation":"把工程总量看作1，两人效率之和为1/10+1/15=(10+15)/150，合作需要150÷(10+15)=6天。","exam":"通用基础","__sub":"工程问题","diff":1},{"id":"sl-40941","module":"shuliang","prompt":"两个数的和是72，差是8。这两个数中较大的数是多少？","options":["44","40","28","72"],"answer":1,"explanation":"小数=（和−差）÷2=32，大数=（和+差）÷2=40。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40942","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才18岁。”乙对甲说：“当我到你这么大时，你就27岁了。”甲今年多少岁？","options":["26","21","24","22"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙18岁，即乙现在为x+d；乙到甲现在这么大时甲27岁，即甲现在为y−d。由y−d−(x+d)=d得d=(27−18)÷3=3，甲今年=27−3=24岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40943","module":"shuliang","prompt":"一项工程，一队单独做需要9天完成，二队单独做需要30天完成。现两人合作3天后，剩余部分由二队单独完成，还需要多少天？","options":["30","27","18","17"],"answer":3,"explanation":"两人每天合作完成1/9+1/30=(9+30)/270，3天完成117/270，剩153/270；二队每天完成1/30，还需30×153/270=17天。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-40944","module":"shuliang","prompt":"某商场促销“满200减60”，小明购买了标价800元的商品（满足优惠条件）。实际付款相当于打几折？","options":["8折","7折","6折","3折"],"answer":1,"explanation":"优惠后实付800−4×60=560元，560÷800=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40945","module":"shuliang","prompt":"甲、乙两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地56千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地60千米处。问A、B两地相距多少千米？","options":["168","140","104","114"],"answer":3,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且甲行56千米，故第二次相遇时甲共行168千米。168大于一个全程而小于两个全程，说明甲已从B地折返，其位置距A地为2S−168（S为全程）。由2S−168=60，解得S=114千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40946","module":"shuliang","prompt":"4个正整数之和为54（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["14","15","12","13"],"answer":0,"explanation":"最大数最小时各数尽量平均，54÷4=13余2，故最大数至少为14（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40947","module":"shuliang","prompt":"某商品按定价出售每件可赚30元，若按定价的8折出售，每件将亏损20元。该商品的进价是多少元？","options":["50","236","205","220"],"answer":3,"explanation":"设进价为C，定价为C+30；8折售价为8/10×(C+30)=C−20，解得C=220元。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40948","module":"shuliang","prompt":"某商品进价每件20元，售价每件40元时每天可卖228件。售价每提高1元，每天少卖6件。要使每天利润最大，售价应定为每件多少元？","options":["49","51","46","40"],"answer":0,"explanation":"设售价提高k元，每天利润=(20+k)×(228−6k)，是关于k的二次函数，当k=9时最大，此时售价=40+9=49元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40949","module":"shuliang","prompt":"6个正整数之和为32（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["7","6","5","9"],"answer":1,"explanation":"最大数最小时各数尽量平均，32÷6=5余2，故最大数至少为6（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40950","module":"shuliang","prompt":"6个正整数之和为85（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["14","17","13","15"],"answer":3,"explanation":"最大数最小时各数尽量平均，85÷6=14余1，故最大数至少为15（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40951","module":"shuliang","prompt":"一项工程，老周先做18天、老吴再做8天恰好完成；若老吴先做18天、老周再做8天也恰好完成。两人合作，需要多少天完成？","options":["13","26","10","14"],"answer":0,"explanation":"设老周每天完成x、老吴每天完成y，由两种情形得mx+ny=1且nx+my=1，两式相减得x=y；代入得(m+n)x=1，合作需1÷(2x)=26÷2=13天。","exam":"通用基础","__sub":"工程问题","diff":3},{"id":"sl-40952","module":"shuliang","prompt":"一辆汽车从甲地到乙地，去程每小时行72千米，按原路返回时每小时行56千米。该车往返全程的平均速度是多少千米/小时？","options":["63","64","65","62"],"answer":0,"explanation":"设单程为1，平均速度=总路程÷总时间=2÷(1/72+1/56)=2×72×56÷(72+56)=63千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40953","module":"shuliang","prompt":"甲接水需要4分钟，乙接水需要9分钟，丙接水需要5分钟，丁接水需要6分钟，戊接水需要7分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["75","86","50","31"],"answer":2,"explanation":"让用时短的人先接水可使总等待时间最短。按4、5、6、7、9的顺序，总等待=4×4+5×3+6×2+7×1+9×0=50分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40954","module":"shuliang","prompt":"把153个名额按8:4:5的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["36","72","108","81"],"answer":1,"explanation":"总份数=8+4+5=17，每份153÷17=9个，最多的班级分得8×9=72个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40955","module":"shuliang","prompt":"某商品按进价加价80%定价，然后按8折出售，仍可获利。该商品的利润率是多少？","options":["39%","64%","52%","44%"],"answer":3,"explanation":"设进价为100，售价=100×(1+80%)×8/10=144，利润率=144−100=44%。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-40956","module":"shuliang","prompt":"某商品进价每件30元，售价每件60元时每天可卖208件。售价每提高1元，每天少卖4件。要使每天利润最大，售价应定为每件多少元？","options":["60","73","69","71"],"answer":3,"explanation":"设售价提高k元，每天利润=(30+k)×(208−4k)，是关于k的二次函数，当k=11时最大，此时售价=60+11=71元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40957","module":"shuliang","prompt":"两个数的和是112，差是18。这两个数中较大的数是多少？","options":["65","74","38","112"],"answer":0,"explanation":"小数=（和−差）÷2=47，大数=（和+差）÷2=65。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40958","module":"shuliang","prompt":"张三和李四分别从相距320千米的两地同时出发，相向而行。张三每小时行31千米，李四每小时行49千米，经过多少小时两车相遇？","options":["5","4","3","49"],"answer":1,"explanation":"两车速度之和为31+49=80千米/小时，相遇时间=320÷80=4小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40959","module":"shuliang","prompt":"袋中有6个红球和7个白球，它们只有颜色不同。从中任取一个，取到红球的概率是多少？","options":["1/2","7/13","1","6/13"],"answer":3,"explanation":"共有13个球，红球6个，取到红球的概率为6/13。","exam":"通用基础","__sub":"概率问题","diff":1},{"id":"sl-40960","module":"shuliang","prompt":"数列{aₙ}满足a₁=1，aₙ₊₁=2aₙ+1，则a6等于多少？","options":["62","67","63","64"],"answer":2,"explanation":"变形得aₙ₊₁+1=2(aₙ+1)，故aₙ+1=(1+1)×2^(n−1)，a6=(1+1)×32−1=63。","exam":"通用基础","__sub":"数列问题","diff":2},{"id":"sl-40961","module":"shuliang","prompt":"一列火车长211米，以每秒30米的速度通过一座长1230米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["48","7","41","50"],"answer":0,"explanation":"火车完全过桥需行驶211+1230=1441米，时间=1441÷30=48秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40962","module":"shuliang","prompt":"快车在慢车后方14千米处，两人同时同向出发。快车每小时行45千米，慢车每小时行31千米，经过多少小时快车追上慢车？","options":["3","1","14","45"],"answer":1,"explanation":"每小时快车比慢车多行45-31=14千米，追及时间=14÷14=1小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40963","module":"shuliang","prompt":"甲数是乙数的2倍，两数之和是78。乙数是多少？","options":["26","52","28","24"],"answer":0,"explanation":"乙数为1份，甲数为2份，共3份；乙数=78÷3=26。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40964","module":"shuliang","prompt":"甲种卡车每次可运6吨货物，耗油12升；乙种卡车每次可运2吨货物，耗油6升。现要运送60吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["114","128","120","180"],"answer":2,"explanation":"甲车每吨耗油12/6升，乙车每吨耗油6/2升，甲车更省。尽量用甲车：10车次运60吨，余0吨用乙车0次，共耗油120升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40965","module":"shuliang","prompt":"一个长方形的长为9米，宽为18米，它的周长是多少米？","options":["56","162","27","54"],"answer":3,"explanation":"长方形周长=2×（长+宽）=2×(9+18)=54米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40966","module":"shuliang","prompt":"一列火车长259米，以每秒31米的速度通过一座长2108米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["8","76","68","78"],"answer":1,"explanation":"火车完全过桥需行驶259+2108=2367米，时间=2367÷31=76秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40967","module":"shuliang","prompt":"一个圆锥与一个圆柱等底等高，圆柱的体积是9立方分米。圆锥的体积是多少立方分米？","options":["3","9","4","18"],"answer":0,"explanation":"等底等高的圆锥体积是圆柱的1/3，即9÷3=3立方分米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40968","module":"shuliang","prompt":"同一时刻，一根6米高的标杆在阳光下的影长为9米，附近一棵大树的影长为18米。这棵大树的高度是多少米？","options":["24","12","13","18"],"answer":1,"explanation":"同一时刻物高与影长成正比，树高=6×18÷9=12米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40969","module":"shuliang","prompt":"一个正方形的边长扩大到原来的5倍，它的面积扩大到原来的多少倍？","options":["5","25","10","30"],"answer":1,"explanation":"边长扩大5倍，面积扩大5×5=25倍。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40970","module":"shuliang","prompt":"某商场促销“满300减90”，小明购买了标价900元的商品（满足优惠条件）。实际付款相当于打几折？","options":["7折","8折","6折","3折"],"answer":0,"explanation":"优惠后实付900−3×90=630元，630÷900=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40971","module":"shuliang","prompt":"甲数是乙数的3倍，两数之和是228。乙数是多少？","options":["57","171","62","55"],"answer":0,"explanation":"乙数为1份，甲数为3份，共4份；乙数=228÷4=57。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40972","module":"shuliang","prompt":"某班同学中，参加语文兴趣小组的有22人，参加数学兴趣小组的有23人，两个小组都参加的有17人。两个小组至少参加一个的共有多少人？","options":["62","45","28","1"],"answer":2,"explanation":"都参加的17人被算了两次，需减去一次，故至少参加一个的人数=22+23−17=28人。","exam":"通用基础","__sub":"容斥原理","diff":1},{"id":"sl-40973","module":"shuliang","prompt":"把104个名额按3:2:3的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["26","39","65","40"],"answer":1,"explanation":"总份数=3+2+3=8，每份104÷8=13个，最多的班级分得3×13=39个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40974","module":"shuliang","prompt":"某商品进价每件50元，售价每件70元时每天可卖66件。售价每提高1元，每天少卖3件。要使每天利润最大，售价应定为每件多少元？","options":["71","73","70","60"],"answer":0,"explanation":"设售价提高k元，每天利润=(20+k)×(66−3k)，是关于k的二次函数，当k=1时最大，此时售价=70+1=71元。","exam":"通用基础","__sub":"利润问题","diff":3},{"id":"sl-40975","module":"shuliang","prompt":"同一时刻，一根6米高的标杆在阳光下的影长为3米，附近一棵大树的影长为9米。这棵大树的高度是多少米？","options":["15","18","19","9"],"answer":1,"explanation":"同一时刻物高与影长成正比，树高=6×9÷3=18米。","exam":"通用基础","__sub":"几何问题","diff":2},{"id":"sl-40976","module":"shuliang","prompt":"小明在小红后方155千米处，两人同时同向出发。小明每小时行88千米，小红每小时行57千米，经过多少小时小明追上小红？","options":["5","6","7","155"],"answer":0,"explanation":"每小时小明比小红多行88-57=31千米，追及时间=155÷31=5小时。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40977","module":"shuliang","prompt":"已知等差数列的首项为3，公差为4，则它的第8项是多少？","options":["32","35","27","31"],"answer":3,"explanation":"等差数列第n项=首项+(n−1)×公差=3+(8-1)×4=31。","exam":"通用基础","__sub":"数列问题","diff":1},{"id":"sl-40978","module":"shuliang","prompt":"已知等差数列的前10项和为180，前20项和为560，则该数列的公差是多少？","options":["3","2","1","38"],"answer":1,"explanation":"S20−2×S10=(560)−2×(180)=200=100d（第11到20项之和比前10项之和多100d），故d=2。","exam":"通用基础","__sub":"数列问题","diff":3},{"id":"sl-40979","module":"shuliang","prompt":"甲数与乙数之比为3:5，乙数与丙数之比为5:4。甲数是丙数的多少倍？","options":["4/3","3/4","4/5","12/25"],"answer":1,"explanation":"甲:丙=3×5:5×4=15:20，甲是丙的3/4倍。","exam":"通用基础","__sub":"和差倍比","diff":2},{"id":"sl-40980","module":"shuliang","prompt":"彩旗按“甲、乙、丙、丁、戊”的顺序循环排列，第102面彩旗是什么颜色？","options":["戊","丙","甲","乙"],"answer":3,"explanation":"周期为5，102÷5=20余2，第102面旗对应周期中的第2个，即“乙”。","exam":"通用基础","__sub":"周期问题","diff":1},{"id":"sl-40981","module":"shuliang","prompt":"甲数是乙数的4倍，两数之和是80。乙数是多少？","options":["13","64","22","16"],"answer":3,"explanation":"乙数为1份，甲数为4份，共5份；乙数=80÷5=16。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40982","module":"shuliang","prompt":"把182个名额按5:3:5的比例分配给三个班级，则分得最多的班级分得多少个名额？","options":["112","42","70","71"],"answer":2,"explanation":"总份数=5+3+5=13，每份182÷13=14个，最多的班级分得5×14=70个。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-40983","module":"shuliang","prompt":"甲接水需要4分钟，乙接水需要3分钟，丙接水需要5分钟，丁接水需要12分钟，他们依次在一个水龙头前接水（顺序可自行安排）。要使所有人等待的总时间最短，最短总等待时间是多少分钟？（等待时间=接水开始前累计的等待分钟数）","options":["50","22","44","24"],"answer":1,"explanation":"让用时短的人先接水可使总等待时间最短。按3、4、5、12的顺序，总等待=3×3+4×2+5×1+12×0=22分钟。","exam":"通用基础","__sub":"统筹问题","diff":3},{"id":"sl-40984","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需11小时，逆流需21小时，两码头相距231千米。该轮船在静水中的速度是多少千米/小时？","options":["15","5","21","16"],"answer":3,"explanation":"顺流速度=231÷11=21千米/小时，逆流速度=231÷21=11千米/小时；静水速度=(21+11)÷2=16千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40985","module":"shuliang","prompt":"甲和乙的速度比为5:4，两人同时同地同向出发赛跑，当甲到达终点时，乙距终点还有40米。赛道全程是多少米？","options":["170","217","200","95"],"answer":2,"explanation":"同一时间内路程比等于速度比，乙走了全程的4/5，还差全程的1/5=40米，故全程=40×5÷1=200米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40986","module":"shuliang","prompt":"甲种卡车每次可运4吨货物，耗油13升；乙种卡车每次可运2吨货物，耗油8升。现要运送16吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["48","55","52","64"],"answer":2,"explanation":"甲车每吨耗油13/4升，乙车每吨耗油8/2升，甲车更省。尽量用甲车：4车次运16吨，余0吨用乙车0次，共耗油52升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40987","module":"shuliang","prompt":"某单位员工中，参加篮球赛的有21人，参加羽毛球赛的有23人，参加乒乓球赛的有23人；同时参加篮球和羽毛球的有12人，参加篮球和乒乓球的有10人，参加羽毛球和乒乓球的有10人，三项都参加的有4人。只参加其中一项比赛的有多少人？","options":["19","15","12","39"],"answer":1,"explanation":"只参加篮球=21−12−10+4=3人；同理只参加羽毛球=5人，只参加乒乓球=7人；合计3+5+7=15人。","exam":"通用基础","__sub":"容斥原理","diff":3},{"id":"sl-40988","module":"shuliang","prompt":"4个正整数之和为24（每个数至少为1），要使其中最大的数尽可能小，则这个最大的数最小是多少？","options":["5","7","6","9"],"answer":2,"explanation":"最大数最小时各数尽量平均，24÷4=6余0，故最大数至少为6（且可以做到）。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40989","module":"shuliang","prompt":"小明、小红两车分别从A、B两地同时出发，相向而行，第一次相遇在距A地47千米处。相遇后两车继续前行，各自到达对方出发地后立即折返，第二次相遇仍在距A地45千米处。问A、B两地相距多少千米？","options":["93","117","76","141"],"answer":0,"explanation":"第二次相遇时两车共行3个全程，第一次相遇时共行1个全程且小明行47千米，故第二次相遇时小明共行141千米。141大于一个全程而小于两个全程，说明小明已从B地折返，其位置距A地为2S−141（S为全程）。由2S−141=45，解得S=93千米。","exam":"通用基础","__sub":"行程问题","diff":3},{"id":"sl-40990","module":"shuliang","prompt":"小明和小红的速度比为9:3，两人同时同地同向出发赛跑，当小明到达终点时，小红距终点还有20米。赛道全程是多少米？","options":["57","30","-9","180"],"answer":1,"explanation":"同一时间内路程比等于速度比，小红走了全程的3/9，还差全程的6/9=20米，故全程=20×9÷6=30米。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40991","module":"shuliang","prompt":"一列火车长200米，以每秒13米的速度通过一座长611米的大桥，从车头上桥到车尾离桥共需多少秒？","options":["15","62","47","65"],"answer":1,"explanation":"火车完全过桥需行驶200+611=811米，时间=811÷13=62秒。","exam":"通用基础","__sub":"行程问题","diff":1},{"id":"sl-40992","module":"shuliang","prompt":"一轮船在两个码头之间航行，顺流需22小时，逆流需30小时，两码头相距660千米。该轮船在静水中的速度是多少千米/小时？","options":["4","26","30","24"],"answer":1,"explanation":"顺流速度=660÷22=30千米/小时，逆流速度=660÷30=22千米/小时；静水速度=(30+22)÷2=26千米/小时。","exam":"通用基础","__sub":"行程问题","diff":2},{"id":"sl-40993","module":"shuliang","prompt":"某商场促销“满300减90”，小明购买了标价600元的商品（满足优惠条件）。实际付款相当于打几折？","options":["3折","8折","6折","7折"],"answer":3,"explanation":"优惠后实付600−2×90=420元，420÷600=7/10，相当于打7折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-40994","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才18岁。”乙对甲说：“当我到你这么大时，你就54岁了。”甲今年多少岁？","options":["44","30","42","40"],"answer":2,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙18岁，即乙现在为x+d；乙到甲现在这么大时甲54岁，即甲现在为y−d。由y−d−(x+d)=d得d=(54−18)÷3=12，甲今年=54−12=42岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40995","module":"shuliang","prompt":"甲对乙说：“当我像你这么大时，你才4岁。”乙对甲说：“当我到你这么大时，你就25岁了。”甲今年多少岁？","options":["18","11","21","17"],"answer":0,"explanation":"年龄差不变，设差为d：甲像乙现在这么大时乙4岁，即乙现在为x+d；乙到甲现在这么大时甲25岁，即甲现在为y−d。由y−d−(x+d)=d得d=(25−4)÷3=7，甲今年=25−7=18岁。","exam":"通用基础","__sub":"年龄问题","diff":3},{"id":"sl-40996","module":"shuliang","prompt":"一个长方形的长为7米，宽为6米，它的面积是多少平方米？","options":["26","42","13","49"],"answer":1,"explanation":"长方形面积=长×宽=7×6=42平方米。","exam":"通用基础","__sub":"几何问题","diff":1},{"id":"sl-40997","module":"shuliang","prompt":"甲种卡车每次可运7吨货物，耗油14升；乙种卡车每次可运3吨货物，耗油7升。现要运送28吨货物（货物可分割），两种车均可按需租用，最少需要耗油多少升？","options":["56","61","54","63"],"answer":0,"explanation":"甲车每吨耗油14/7升，乙车每吨耗油7/3升，甲车更省。尽量用甲车：4车次运28吨，余0吨用乙车0次，共耗油56升。","exam":"通用基础","__sub":"最值问题","diff":3},{"id":"sl-40998","module":"shuliang","prompt":"某单位组织125人外出学习，大巴车每辆限乘45人、租金400元，中巴车每辆限乘30人、租金280元。要使租金最省，最少需要多少元？（车辆可不满员）","options":["1073","1346","1200","1400"],"answer":2,"explanation":"大巴每个座位400/45元，中巴每个座位280/30元，比较后尽量用更省的车型组合，逐一试算得最少租金为1200元。","exam":"通用基础","__sub":"统筹问题","diff":2},{"id":"sl-40999","module":"shuliang","prompt":"某商场促销“满300减60”，小明购买了标价1200元的商品（满足优惠条件）。实际付款相当于打几折？","options":["9折","8折","7折","2折"],"answer":1,"explanation":"优惠后实付1200−4×60=960元，960÷1200=4/5，相当于打8折。","exam":"通用基础","__sub":"利润问题","diff":1},{"id":"sl-41000","module":"shuliang","prompt":"两个数的和是66，差是38。这两个数中较大的数是多少？","options":["-5","71","52","66"],"answer":2,"explanation":"小数=（和−差）÷2=14，大数=（和+差）÷2=52。","exam":"通用基础","__sub":"和差倍比","diff":1},{"id":"sl-1468","module":"shuliang","prompt":"某车间按效率分配生产任务，甲效率是乙的1.5倍。两人合作6天完成全部任务的100%，若乙单独完成全部任务需要多少天？","options":["12天","15天","18天","20天"],"answer":1,"explanation":"甲效率1.5，乙效率1，合作效率2.5，6天完成总量=2.5×6=15。乙单独需15÷1=15天。故选B。","exam":"通用基础","__sub":"工程问题","diff":2},{"id":"sl-1607","module":"shuliang","prompt":"某商店以每件90元购进一批衬衫，加价50%定价销售。售出80%后，剩下的打五折促销。问全部售完后利润率约为多少？","options":["30%","35%","40%","45%"],"answer":1,"explanation":"定价=90×1.5=135元。售出80%收入=135×0.8=108，剩余20%按67.5元卖，收入合计108+67.5×0.2=108+13.5=121.5。利润率=(121.5-90)÷90=35%。故选B。","exam":"通用基础","__sub":"利润问题","diff":2},{"id":"sl-1747","module":"shuliang","prompt":"某单位从8名员工中选派3人参加培训，要求甲、乙两人至少有一人参加，共有多少种选法？","options":["36种","42种","48种","56种"],"answer":0,"explanation":"总选法C(8,3)=56；甲乙都不参加的选法C(6,3)=20；至少一人参加=56-20=36种。故选A。","exam":"通用基础","__sub":"排列组合","diff":3}]);
window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"sl-20001","module":"shuliang","diff":1,"prompt":"甲仓库有56吨粮食，乙仓库比甲仓库多20吨，两个仓库共有粮食多少吨？","options":["112","152","132","76"],"answer":2,"explanation":"【和差倍问题】乙仓库有56+20=76吨，共有56+76=132吨。"},{"id":"sl-20005","module":"shuliang","diff":1,"prompt":"甲收集的邮票是乙的2倍，甲比乙多20张，乙收集了多少张？","options":["40","30","20","21"],"answer":2,"explanation":"【和差倍问题】甲比乙多2-1=1倍，恰好多20张，所以乙有20÷1=20张。"},{"id":"sl-20009","module":"shuliang","diff":1,"prompt":"两个数的和是90，差是10，其中较大的数是多少？","options":["40","10","50","90"],"answer":2,"explanation":"【和差倍问题】大数=（和+差）÷2=（90+10）÷2=50。"},{"id":"sl-20010","module":"shuliang","diff":1,"prompt":"两个数的和是68，差是8，其中较大的数是多少？","options":["68","30","8","38"],"answer":3,"explanation":"【和差倍问题】大数=（和+差）÷2=（68+8）÷2=38。"},{"id":"sl-20012","module":"shuliang","diff":2,"prompt":"甲、乙两人共加工零件48个，甲加工的是乙的3倍，乙加工了多少个？","options":["15","12","24","36"],"answer":1,"explanation":"【和差倍问题】把乙看作1份，甲是3份，共4份，乙=48÷4=12个。"},{"id":"sl-20013","module":"shuliang","diff":2,"prompt":"甲、乙两人共加工零件80个，甲加工的是乙的3倍，乙加工了多少个？","options":["40","60","20","23"],"answer":2,"explanation":"【和差倍问题】把乙看作1份，甲是3份，共4份，乙=80÷4=20个。"},{"id":"sl-20014","module":"shuliang","diff":2,"prompt":"甲、乙两数的和是105，甲比乙多35，甲数是多少？","options":["105","35","70","65"],"answer":2,"explanation":"【和差倍问题】甲=（105+35）÷2=70。"},{"id":"sl-20015","module":"shuliang","diff":1,"prompt":"今年甲28岁，乙26岁，再过8年，甲比乙大多少岁？","options":["8","10","2","46"],"answer":2,"explanation":"【年龄问题】年龄差不变，今年差28-26=2岁，再过8年仍大2岁。"},{"id":"sl-20019","module":"shuliang","diff":2,"prompt":"今年小明15岁，妈妈的年龄是小明的4倍，再过多少年，小明的年龄是妈妈的一半？","options":["60","15","45","30"],"answer":3,"explanation":"【年龄问题】小明是妈妈的一半即妈妈是小明的2倍。设过n年：2×(15+n)=60+n，解得n=30。"},{"id":"sl-20023","module":"shuliang","diff":2,"prompt":"今年父亲36岁，儿子8岁，多少年后父亲的年龄是儿子的3倍？","options":["6","28","12","9"],"answer":0,"explanation":"【年龄问题】设过n年：36+n=3×(8+n)，解得n=6。"},{"id":"sl-20024","module":"shuliang","diff":2,"prompt":"今年父亲40岁，儿子12岁，多少年后父亲的年龄是儿子的3倍？","options":["5","28","2","4"],"answer":2,"explanation":"【年龄问题】设过n年：40+n=3×(12+n)，解得n=2。"},{"id":"sl-20025","module":"shuliang","diff":2,"prompt":"今年哥哥22岁，弟弟14岁，哥哥多少岁时，哥哥的年龄正好是弟弟的2倍？","options":["22","16","14","24"],"answer":1,"explanation":"【年龄问题】哥哥是弟弟的2倍时，哥哥比弟弟大22-14=8岁，即弟弟那时8岁、哥哥16岁。"},{"id":"sl-20026","module":"shuliang","diff":2,"prompt":"今年哥哥24岁，弟弟16岁，哥哥多少岁时，哥哥的年龄正好是弟弟的2倍？","options":["24","17","16","8"],"answer":2,"explanation":"【年龄问题】哥哥是弟弟的2倍时，哥哥比弟弟大24-16=8岁，即弟弟那时8岁、哥哥16岁。"},{"id":"sl-20027","module":"shuliang","diff":1,"prompt":"A、B两地相距240千米，甲车从A地、乙车从B地同时出发相向而行，甲车每小时行80千米，乙车每小时行40千米，两车几小时后相遇？","options":["1","4","2","3"],"answer":2,"explanation":"【行程问题】速度和=80+40=120千米/小时，相遇时间=240÷120=2小时。"},{"id":"sl-20031","module":"shuliang","diff":1,"prompt":"甲、乙两人同时同地同向出发，甲每小时行90千米，乙每小时行50千米，4小时后甲在乙前面多少千米？","options":["560","210","110","160"],"answer":3,"explanation":"【行程问题】速度差=90-50=40千米/小时，4小时相距40×4=160千米。"},{"id":"sl-20032","module":"shuliang","diff":1,"prompt":"甲、乙两人同时同地同向出发，甲每小时行80千米，乙每小时行55千米，5小时后甲在乙前面多少千米？","options":["180","70","125","675"],"answer":2,"explanation":"【行程问题】速度差=80-55=25千米/小时，5小时相距25×5=125千米。"},{"id":"sl-20034","module":"shuliang","diff":2,"prompt":"乙先出发，甲出发时乙已在前80千米。甲每小时行70千米，乙每小时行50千米，甲出发后几小时追上乙？","options":["1","5","4","3"],"answer":2,"explanation":"【行程问题】追及时间=路程差÷速度差=80÷(70-50)=4小时。"},{"id":"sl-20038","module":"shuliang","diff":2,"prompt":"某人骑车去程速度为每小时40千米，沿原路返回时速度为每小时60千米，往返的平均速度是每小时多少千米？","options":["40","48","50","60"],"answer":1,"explanation":"【行程问题】等路程平均速度=2×40×60÷(40+60)=4800÷100=48千米/小时，不是两速度的算术平均。"},{"id":"sl-20042","module":"shuliang","diff":3,"prompt":"一列火车长120米，以每秒40米的速度通过一座长2280米的大桥，需要多少秒？","options":["60","65","3","57"],"answer":0,"explanation":"【行程问题】过桥路程=桥长+车长=2280+120=2400米，时间=2400÷40=60秒。"},{"id":"sl-20046","module":"shuliang","diff":3,"prompt":"一艘船顺流航行120千米用了3小时，逆流航行同样路程用了4小时，船在静水中的速度是每小时多少千米？","options":["40","17","35","30"],"answer":2,"explanation":"【行程问题】顺水速=120÷3=40，逆水速=120÷4=30，静水速=（40+30）÷2=35千米/小时。"},{"id":"sl-20047","module":"shuliang","diff":3,"prompt":"一艘船顺流航行120千米用了2小时，逆流航行同样路程用了3小时，船在静水中的速度是每小时多少千米？","options":["24","40","60","50"],"answer":3,"explanation":"【行程问题】顺水速=120÷2=60，逆水速=120÷3=40，静水速=（60+40）÷2=50千米/小时。"},{"id":"sl-20048","module":"shuliang","diff":3,"prompt":"甲、乙两人沿300米的环形跑道同时同地同向出发，甲每秒跑7米，乙每秒跑5米，甲出发后多少秒第一次追上乙？","options":["150","25","200","75"],"answer":0,"explanation":"【行程问题】第一次追上即甲比乙多跑一圈，时间=300÷(7-5)=150秒。"},{"id":"sl-20049","module":"shuliang","diff":3,"prompt":"甲、乙两人沿400米的环形跑道同时同地同向出发，甲每秒跑6米，乙每秒跑4米，甲出发后多少秒第一次追上乙？","options":["200","100","40","250"],"answer":0,"explanation":"【行程问题】第一次追上即甲比乙多跑一圈，时间=400÷(6-4)=200秒。"},{"id":"sl-20051","module":"shuliang","diff":1,"prompt":"一项工程，甲队单独做需要10天完成，乙队单独做需要15天完成，两队合作需要多少天完成？","options":["6","25","7","5"],"answer":0,"explanation":"【工程问题】甲每天做1/10，乙每天做1/15，合作每天做1/10+1/15，需要150÷25=6天。"},{"id":"sl-20056","module":"shuliang","diff":2,"prompt":"一项工程，甲单独做16天完成，乙单独做8天完成。甲先单独做6天，剩下的由乙单独做，乙还需要多少天？","options":["7","2","5","10"],"answer":2,"explanation":"【工程问题】甲做6天完成6/16，剩10/16，乙需8×10/16=5天。"},{"id":"sl-20060","module":"shuliang","diff":3,"prompt":"一项工程，甲单独做6天完成，乙单独做12天完成，丙单独做12天完成，三队合作需要多少天完成？","options":["2","10","3","4"],"answer":2,"explanation":"【工程问题】三人每天共做1/6+1/12+1/12，合作需要3天完成。"},{"id":"sl-20064","module":"shuliang","diff":3,"prompt":"一项工程，甲单独做6天完成，乙单独做12天完成。两人轮流工作，甲先做一天、乙再做一天，如此交替，完成这项工程共需多少天？","options":["14","10","9","12"],"answer":3,"explanation":"【工程问题】每2天完成1/6+1/12，共需6轮即12天。"},{"id":"sl-20068","module":"shuliang","diff":1,"prompt":"某商品进价200元，按利润率20%定价出售，售价是多少元？","options":["240","220","40","400"],"answer":0,"explanation":"【经济利润】售价=进价×(1+利润率)=200×(1+20%)=240元。"},{"id":"sl-20072","module":"shuliang","diff":1,"prompt":"某商品进价120元，售价150元，利润率是多少？","options":["25","15","35","20"],"answer":0,"explanation":"【经济利润】利润率=利润÷进价=(150-120)÷120=25%。"},{"id":"sl-20076","module":"shuliang","diff":2,"prompt":"某商品定价200元，打9折出售后仍能获利20%，这件商品的进价是多少元？","options":["158","142","150","180"],"answer":2,"explanation":"【经济利润】售价=200×9/10=180元，进价=180÷(1+20%)=150元。"},{"id":"sl-20080","module":"shuliang","diff":2,"prompt":"某商品按定价出售可获利25%，若按定价打几折出售刚好保本？","options":["9","7","8","7.5"],"answer":2,"explanation":"【经济利润】保本即售价=进价，设打y折：y/10=1÷(1+25%)，y=8，即8折。"},{"id":"sl-20081","module":"shuliang","diff":2,"prompt":"某商品按定价出售可获利100%，若按定价打几折出售刚好保本？","options":["5","6","4","4.5"],"answer":0,"explanation":"【经济利润】保本即售价=进价，设打y折：y/10=1÷(1+100%)，y=5，即5折。"},{"id":"sl-20082","module":"shuliang","diff":3,"prompt":"某商品进价8元，售价12元时每天可卖100件；售价每上涨1元，每天少卖10件。售价定为多少元时，每天利润最大？","options":["14","13","15","16"],"answer":2,"explanation":"【经济利润】设涨价n元，利润=(4+n)(100-10n)=10(4+n)(10-n)，当4+n=10-n即n=3时最大，定价8+3=15元。"},{"id":"sl-20083","module":"shuliang","diff":3,"prompt":"某商店同时卖出两件商品，第一件进价150元，获利40%；第二件进价250元，亏损20%。两件商品合计盈亏多少元？","options":["50","10","60","110"],"answer":1,"explanation":"【经济利润】第一件赚60元，第二件亏50元，合计60-50=10元（赚10元）。"},{"id":"sl-20084","module":"shuliang","diff":3,"prompt":"某商店同时卖出两件商品，第一件进价200元，获利30%；第二件进价100元，亏损20%。两件商品合计盈亏多少元？","options":["20","60","40","80"],"answer":2,"explanation":"【经济利润】第一件赚60元，第二件亏20元，合计60-20=40元（赚40元）。"},{"id":"sl-20086","module":"shuliang","diff":2,"prompt":"从9名同学中选出2名参加比赛，共有多少种不同的选法？","options":["36","34","38","72"],"answer":0,"explanation":"【排列组合】选法与顺序无关，用组合数：C(9,2)=36种。"},{"id":"sl-20090","module":"shuliang","diff":2,"prompt":"3名同学站成一排拍照，共有多少种不同的站法？","options":["6","9","12","3"],"answer":0,"explanation":"【排列组合】全排列：3×2×1=6种。"},{"id":"sl-20091","module":"shuliang","diff":2,"prompt":"5名同学站成一排拍照，共有多少种不同的站法？","options":["240","60","120","125"],"answer":2,"explanation":"【排列组合】全排列：5×4×3×2×1=120种。"},{"id":"sl-20093","module":"shuliang","diff":2,"prompt":"袋中有3个红球、9个白球，除颜色外完全相同，从中摸出1个球，摸到红球的概率是多少？","options":["1/3","1/4","3/11","3/4"],"answer":1,"explanation":"【概率】红球3个，共12个球，摸到红球概率=1/4。"},{"id":"sl-20097","module":"shuliang","diff":3,"prompt":"袋中有5个红球、3个白球，从中一次摸出2个球，两个都是红球的概率是多少？","options":["5/8","5/15","5/14","25/64"],"answer":2,"explanation":"【概率】从8个球中摸2个共C(8,2)=28种，两球全红有C(5,2)=10种，概率=5/14。"},{"id":"sl-20098","module":"shuliang","diff":3,"prompt":"袋中有3个红球、2个白球，从中一次摸出2个球，两个都是红球的概率是多少？","options":["3/5","9/25","3/10","3/11"],"answer":2,"explanation":"【概率】从5个球中摸2个共C(5,2)=10种，两球全红有C(3,2)=3种，概率=3/10。"},{"id":"sl-20100","module":"shuliang","diff":3,"prompt":"4名同学站成一排，甲既不站排头也不站排尾，共有多少种站法？","options":["16","12","24","20"],"answer":1,"explanation":"【排列组合】甲在两端共2×3!=12种，总24种，故24-12=12种。"},{"id":"sl-20101","module":"shuliang","diff":3,"prompt":"5名同学站成一排，甲既不站排头也不站排尾，共有多少种站法？","options":["77","72","120","48"],"answer":1,"explanation":"【排列组合】甲在两端共2×4!=48种，总120种，故120-48=72种。"},{"id":"sl-20102","module":"shuliang","diff":3,"prompt":"袋中有5个次品、5个正品，从中任取2个，至少有1个次品的概率是多少？","options":["7/10","7/9","2/9","5/10"],"answer":1,"explanation":"【概率】取2个共45种，全是正品10种，至少1个次品35种，概率=7/9。"},{"id":"sl-20103","module":"shuliang","diff":3,"prompt":"袋中有4个次品、4个正品，从中任取2个，至少有1个次品的概率是多少？","options":["4/8","3/14","11/14","11/15"],"answer":2,"explanation":"【概率】取2个共28种，全是正品6种，至少1个次品22种，概率=11/14。"},{"id":"sl-20105","module":"shuliang","diff":1,"prompt":"一个长方形的长是12米，宽是7米，它的周长是多少米？","options":["31","19","38","84"],"answer":2,"explanation":"【几何】周长=（长+宽）×2=（12+7）×2=38米。"},{"id":"sl-20106","module":"shuliang","diff":1,"prompt":"一个长方形的长是12米，宽是6米，它的周长是多少米？","options":["36","30","18","72"],"answer":0,"explanation":"【几何】周长=（长+宽）×2=（12+6）×2=36米。"},{"id":"sl-20108","module":"shuliang","diff":1,"prompt":"一个长方形的长是18米，宽是9米，它的面积是多少平方米？","options":["27","54","180","162"],"answer":3,"explanation":"【几何】面积=长×宽=18×9=162平方米。"},{"id":"sl-20109","module":"shuliang","diff":1,"prompt":"一个长方形的长是15米，宽是7米，它的面积是多少平方米？","options":["105","22","120","44"],"answer":0,"explanation":"【几何】面积=长×宽=15×7=105平方米。"},{"id":"sl-20111","module":"shuliang","diff":1,"prompt":"一个圆的半径是5厘米，它的面积是多少平方厘米？（π取3.14）","options":["78.5","31.400000000000002","15.700000000000001","81.64"],"answer":0,"explanation":"【几何】圆面积=πr²=3.14×5²=78.5平方厘米。"},{"id":"sl-20112","module":"shuliang","diff":1,"prompt":"一个圆的半径是20厘米，它的面积是多少平方厘米？（π取3.14）","options":["1259.14","1256","62.800000000000004","125.60000000000001"],"answer":1,"explanation":"【几何】圆面积=πr²=3.14×20²=1256.0平方厘米。"},{"id":"sl-20114","module":"shuliang","diff":2,"prompt":"直角三角形的两条直角边分别为6厘米和8厘米，斜边长多少厘米？","options":["14","9","10","11"],"answer":2,"explanation":"【几何】勾股定理：斜边=√(6²+8²)=√100=10厘米。"},{"id":"sl-20115","module":"shuliang","diff":2,"prompt":"直角三角形的两条直角边分别为5厘米和12厘米，斜边长多少厘米？","options":["14","12","17","13"],"answer":3,"explanation":"【几何】勾股定理：斜边=√(5²+12²)=√169=13厘米。"},{"id":"sl-20117","module":"shuliang","diff":2,"prompt":"一个长方体的长、宽、高分别为3厘米、5厘米、8厘米，它的体积是多少立方厘米？","options":["120","123","16","158"],"answer":0,"explanation":"【几何】长方体体积=长×宽×高=3×5×8=120立方厘米。"},{"id":"sl-20118","module":"shuliang","diff":2,"prompt":"一个长方体的长、宽、高分别为2厘米、10厘米、5厘米，它的体积是多少立方厘米？","options":["100","102","17","160"],"answer":0,"explanation":"【几何】长方体体积=长×宽×高=2×10×5=100立方厘米。"},{"id":"sl-20120","module":"shuliang","diff":2,"prompt":"一个正方体的棱长是10厘米，它的棱长总和是多少厘米？","options":["100","120","600","130"],"answer":1,"explanation":"【几何】正方体有12条棱，棱长总和=12×10=120厘米。"},{"id":"sl-20121","module":"shuliang","diff":2,"prompt":"一个正方体的棱长是6厘米，它的棱长总和是多少厘米？","options":["78","36","216","72"],"answer":3,"explanation":"【几何】正方体有12条棱，棱长总和=12×6=72厘米。"},{"id":"sl-20122","module":"shuliang","diff":3,"prompt":"一个长方形的长增加10%，宽减少10%，它的面积变化情况是？","options":["不变","减少6%","增加1%","减少1%"],"answer":3,"explanation":"【几何】面积变为原来的(1+10%)×(1-10%)=99%，减少了1%。"},{"id":"sl-20123","module":"shuliang","diff":2,"prompt":"某班有50名同学，参加语文兴趣小组的有26人，参加数学兴趣小组的有24人，两个小组都参加的有8人，两个小组都没参加的有多少人？","options":["8","6","16","42"],"answer":0,"explanation":"【容斥原理】至少参加一组的有26+24-8=42人，都没参加的有50-42=8人。"},{"id":"sl-20127","module":"shuliang","diff":2,"prompt":"参加合唱队的有28人，参加舞蹈队的有22人，两个队都参加的有10人，参加合唱队或舞蹈队的共有多少人？","options":["30","40","60","50"],"answer":1,"explanation":"【容斥原理】28+22-10=40人，重复的10人只算一次。"},{"id":"sl-20128","module":"shuliang","diff":2,"prompt":"参加合唱队的有35人，参加舞蹈队的有30人，两个队都参加的有15人，参加合唱队或舞蹈队的共有多少人？","options":["35","50","80","65"],"answer":1,"explanation":"【容斥原理】35+30-15=50人，重复的15人只算一次。"},{"id":"sl-20130","module":"shuliang","diff":3,"prompt":"某年级共60人，参加数学竞赛的32人，参加物理竞赛的28人，参加化学竞赛的20人；同时参加数学和物理的10人，数学和化学的8人，物理和化学的6人，三项都参加的2人。三项竞赛都没参加的有多少人？","options":["2","4","56","58"],"answer":0,"explanation":"【容斥原理】至少参加一项的有32+28+20-10-8-6+2=58人，都没参加的有60-58=2人。"},{"id":"sl-20131","module":"shuliang","diff":3,"prompt":"某年级共80人，参加数学竞赛的40人，参加物理竞赛的35人，参加化学竞赛的30人；同时参加数学和物理的12人，数学和化学的10人，物理和化学的8人，三项都参加的3人。三项竞赛都没参加的有多少人？","options":["2","78","4","5"],"answer":0,"explanation":"【容斥原理】至少参加一项的有40+35+30-12-10-8+3=78人，都没参加的有80-78=2人。"},{"id":"sl-20133","module":"shuliang","diff":3,"prompt":"参加数学竞赛的32人，物理竞赛的28人，化学竞赛的20人；数学物理都参加的10人，数学化学都参加的8人，物理化学都参加的6人，三项都参加的2人。只参加一项竞赛的有多少人？","options":["36","56","38","40"],"answer":2,"explanation":"【容斥原理】只参加一项=总数-重复人数，即32+28+20-2×(10+8+6)+3×2=38人。"},{"id":"sl-20134","module":"shuliang","diff":3,"prompt":"参加数学竞赛的25人，物理竞赛的22人，化学竞赛的15人；数学物理都参加的8人，数学化学都参加的6人，物理化学都参加的5人，三项都参加的2人。只参加一项竞赛的有多少人？","options":["28","32","43","30"],"answer":3,"explanation":"【容斥原理】只参加一项=总数-重复人数，即25+22+15-2×(8+6+5)+3×2=30人。"},{"id":"sl-20135","module":"shuliang","diff":3,"prompt":"袋中有红、黄、蓝等4种颜色的球各若干个（每种足够多），至少摸出多少个球，才能保证有2个球颜色相同？","options":["8","6","5","4"],"answer":2,"explanation":"【最值问题】最不利情形：每种颜色各摸1个共4个，再摸1个必有2个同色，共4+1=5个。"},{"id":"sl-20139","module":"shuliang","diff":3,"prompt":"某班同学中至少要有多少人，才能保证有3个人在同一个月过生日？","options":["27","24","36","25"],"answer":3,"explanation":"【最值问题】一年有12个月，最不利时每月各有2人共24人，再加1人即可保证，共25人。"},{"id":"sl-20140","module":"shuliang","diff":3,"prompt":"某班同学中至少要有多少人，才能保证有4个人在同一个月过生日？","options":["31","30","33","40"],"answer":0,"explanation":"【最值问题】一年有10个月，最不利时每月各有3人共30人，再加1人即可保证，共31人。"},{"id":"sl-20141","module":"shuliang","diff":3,"prompt":"两个自然数的和是40，这两个数的乘积最大是多少？","options":["420","533","399","400"],"answer":3,"explanation":"【最值问题】两数和一定时，两数越接近乘积越大，取20×20=400。"},{"id":"sl-20142","module":"shuliang","diff":3,"prompt":"两个自然数的和是20，这两个数的乘积最大是多少？","options":["110","133","100","99"],"answer":2,"explanation":"【最值问题】两数和一定时，两数越接近乘积越大，取10×10=100。"},{"id":"sl-20143","module":"shuliang","diff":2,"prompt":"一个盒子里有红、黄、蓝三种颜色的球各12个，至少摸出多少个球，才能保证有2个球颜色相同？","options":["3","4","5","13"],"answer":1,"explanation":"【最值问题】最不利时三种颜色各摸1个，再摸1个必与某个同色，共3+1=4个。"},{"id":"sl-20144","module":"shuliang","diff":2,"prompt":"一个盒子里有红、黄、蓝三种颜色的球各10个，至少摸出多少个球，才能保证有2个球颜色相同？","options":["4","11","3","5"],"answer":0,"explanation":"【最值问题】最不利时三种颜色各摸1个，再摸1个必与某个同色，共3+1=4个。"},{"id":"sl-20145","module":"shuliang","diff":1,"prompt":"彩灯按\"红、黄、蓝\"的顺序循环点亮，第38盏灯是什么颜色？","options":["绿","黄","蓝","红"],"answer":1,"explanation":"【周期问题】38÷3=12余2，第38盏与第2盏相同，是黄色。"},{"id":"sl-20146","module":"shuliang","diff":1,"prompt":"彩灯按\"红、黄、蓝\"的顺序循环点亮，第100盏灯是什么颜色？","options":["黄","蓝","绿","红"],"answer":3,"explanation":"【周期问题】100÷3=33余3，第100盏与第1盏相同，是红色。"},{"id":"sl-20147","module":"shuliang","diff":1,"prompt":"彩灯按\"红、黄、蓝\"的顺序循环点亮，第88盏灯是什么颜色？","options":["红","蓝","绿","黄"],"answer":0,"explanation":"【周期问题】88÷3=29余3，第88盏与第1盏相同，是红色。"},{"id":"sl-20148","module":"shuliang","diff":1,"prompt":"彩灯按\"红、黄、蓝、绿\"的顺序循环点亮，第100盏灯是什么颜色？","options":["红","绿","黄","蓝"],"answer":1,"explanation":"【周期问题】100÷4=25余4，第100盏与第4盏相同，是绿色。"},{"id":"sl-20149","module":"shuliang","diff":1,"prompt":"今天是星期六，再过22天是星期几？","options":["二","三","一","日"],"answer":3,"explanation":"【周期问题】22÷7=3余1，从星期六往后数1天，是星期日。"},{"id":"sl-20150","module":"shuliang","diff":1,"prompt":"今天是星期三，再过45天是星期几？","options":["日","二","六","一"],"answer":2,"explanation":"【周期问题】45÷7=6余3，从星期三往后数3天，是星期六。"},{"id":"sl-20151","module":"shuliang","diff":1,"prompt":"今天是星期四，再过100天是星期几？","options":["日","二","一","六"],"answer":3,"explanation":"【周期问题】100÷7=14余2，从星期四往后数2天，是星期六。"},{"id":"sl-20152","module":"shuliang","diff":1,"prompt":"今天是星期二，再过100天是星期几？","options":["二","四","日","一"],"answer":1,"explanation":"【周期问题】100÷7=14余2，从星期二往后数2天，是星期四。"},{"id":"sl-20153","module":"shuliang","diff":2,"prompt":"某月1日是星期四，该月共有31天，这个月有几个星期一？","options":["4","6","3","5"],"answer":0,"explanation":"【周期问题】该月31天含4个完整周余3天，逐个数得星期一有4个。"},{"id":"sl-20154","module":"shuliang","diff":2,"prompt":"某月1日是星期一，该月共有31天，这个月有几个星期一？","options":["6","7","5","4"],"answer":2,"explanation":"【周期问题】该月31天含4个完整周余3天，逐个数得星期一有5个。"},{"id":"sl-20155","module":"shuliang","diff":2,"prompt":"一串珠子按\"红、红、蓝、蓝、蓝\"的顺序循环排列，第88颗珠子是什么颜色？","options":["白","红","黑","蓝"],"answer":3,"explanation":"【周期问题】周期为5，88÷5=17余3，第88颗是蓝色。"},{"id":"sl-20156","module":"shuliang","diff":2,"prompt":"一串珠子按\"红、红、蓝、蓝、蓝\"的顺序循环排列，第100颗珠子是什么颜色？","options":["红","蓝","黑","白"],"answer":1,"explanation":"【周期问题】周期为5，100÷5=20余5，第100颗是蓝色。"},{"id":"sl-20157","module":"shuliang","diff":2,"prompt":"有100克含糖20%的糖水，加入100克水后，糖水的含糖率是多少？","options":["10","12","40","8"],"answer":0,"explanation":"【浓度问题】糖有100×20%=20克，加水后共200克，含糖率=20÷200=10%。"},{"id":"sl-20161","module":"shuliang","diff":2,"prompt":"将200克浓度10%的盐水与100克浓度40%的盐水混合，混合后盐水的浓度是多少？","options":["40","25","20","10"],"answer":2,"explanation":"【浓度问题】盐共200×10%+100×40%=20+40=60克，共300克，浓度=60÷300=20.0%。"},{"id":"sl-20162","module":"shuliang","diff":2,"prompt":"将150克浓度20%的盐水与50克浓度60%的盐水混合，混合后盐水的浓度是多少？","options":["20","60","30","40"],"answer":2,"explanation":"【浓度问题】盐共150×20%+50×60%=30+30=60克，共200克，浓度=60÷200=30.0%。"},{"id":"sl-20164","module":"shuliang","diff":3,"prompt":"100克浓度为20%的盐水，蒸发掉20克水后，浓度变为多少？","options":["16","20","25","30"],"answer":2,"explanation":"【浓度问题】盐100×20%=20克不变，水剩100-20=80克，浓度=20÷80×100%=25.0%。"},{"id":"sl-20165","module":"shuliang","diff":3,"prompt":"150克浓度为30%的盐水，蒸发掉50克水后，浓度变为多少？","options":["35","50","45","20"],"answer":2,"explanation":"【浓度问题】盐150×30%=45克不变，水剩150-50=100克，浓度=45÷100×100%=45.0%。"},{"id":"sl-20166","module":"shuliang","diff":3,"prompt":"100克浓度为20%的糖水中加入20克糖，新的糖水浓度是多少？","options":["33.33333333333333","40","30","38.33333333333333"],"answer":0,"explanation":"【浓度问题】糖共100×20%+20=20+20=40克，总量100+20=120克，浓度=40÷120×100%=33.33333333333333%。"},{"id":"sl-20167","module":"shuliang","diff":1,"prompt":"在一条长150米的小路一侧植树，每隔5米植一棵，两端都植，一共要植多少棵？","options":["30","31","32","29"],"answer":1,"explanation":"【植树问题】两端都植：棵数=间隔数+1=150÷5+1=31棵。"},{"id":"sl-20168","module":"shuliang","diff":1,"prompt":"在一条长100米的小路一侧植树，每隔20米植一棵，两端都植，一共要植多少棵？","options":["6","4","7","5"],"answer":0,"explanation":"【植树问题】两端都植：棵数=间隔数+1=100÷20+1=6棵。"},{"id":"sl-20170","module":"shuliang","diff":1,"prompt":"在周长为120米的圆形花坛周围植树，每隔5米植一棵，一共要植多少棵？","options":["25","24","26","23"],"answer":1,"explanation":"【植树问题】封闭路线：棵数=间隔数=120÷5=24棵。"},{"id":"sl-20171","module":"shuliang","diff":1,"prompt":"在周长为160米的圆形花坛周围植树，每隔20米植一棵，一共要植多少棵？","options":["7","10","9","8"],"answer":3,"explanation":"【植树问题】封闭路线：棵数=间隔数=160÷20=8棵。"},{"id":"sl-20173","module":"shuliang","diff":2,"prompt":"在一条长100米的小路一侧植树，每隔5米植一棵，两端都不植，一共要植多少棵？","options":["20","19","18","21"],"answer":1,"explanation":"【植树问题】两端不植：棵数=间隔数-1=100÷5-1=19棵。"},{"id":"sl-20174","module":"shuliang","diff":2,"prompt":"在一条长100米的小路一侧植树，每隔20米植一棵，两端都不植，一共要植多少棵？","options":["4","5","3","6"],"answer":0,"explanation":"【植树问题】两端不植：棵数=间隔数-1=100÷20-1=4棵。"},{"id":"sl-20175","module":"shuliang","diff":2,"prompt":"一个实心方阵的最外层每边有8人，这个方阵共有多少人？","options":["64","28","32","56"],"answer":0,"explanation":"【方阵问题】实心方阵总人数=每边人数²=8×8=64人。"},{"id":"sl-20176","module":"shuliang","diff":2,"prompt":"一个实心方阵的最外层每边有10人，这个方阵共有多少人？","options":["40","90","100","36"],"answer":2,"explanation":"【方阵问题】实心方阵总人数=每边人数²=10×10=100人。"},{"id":"sl-20177","module":"shuliang","diff":1,"prompt":"鸡兔同笼，共有12个头，36只脚，鸡有多少只？","options":["7","6","8","11"],"answer":1,"explanation":"【鸡兔同笼】假设全是兔，则有4×12=48只脚，多出48-36=12只，鸡=12÷2=6只。"},{"id":"sl-20181","module":"shuliang","diff":2,"prompt":"老师把一些苹果分给小朋友，如果每人分3个，多6个；如果每人分5个，少6个。一共有多少个苹果？","options":["24","30","6","12"],"answer":0,"explanation":"【盈亏问题】人数=（6+6）÷(5-3)=6人，苹果=6×3+6=24个。"},{"id":"sl-20185","module":"shuliang","diff":1,"prompt":"8个数的平均数是30，加入一个新数后平均数变为33，加入的新数是多少？","options":["3","30","65","57"],"answer":3,"explanation":"【平均数】原总和8×30=240，新总和33×9=297，新数=297-240=57。"},{"id":"sl-20190","module":"shuliang","diff":2,"prompt":"等差数列的首项是3，公差是5，前12项的和是多少？","options":["354","378","48","366"],"answer":3,"explanation":"【数列】等差数列求和=（首项+末项）×项数÷2，末项=3+5×11=58，和=(3+58)×12÷2=366。"},{"id":"sl-20194","module":"shuliang","diff":2,"prompt":"6个数的平均数是20，去掉最大的数30和最小的数10后，剩下的4个数的平均数是多少？","options":["18","21","22","20"],"answer":3,"explanation":"【平均数】总和6×20=120，去掉两数后和为120-30-10=80，平均=80÷4=20。"},{"id":"sl-20198","module":"shuliang","diff":2,"prompt":"甲、乙两人的平均年龄是40岁，乙、丙两人的平均年龄是50岁，甲、丙两人的平均年龄是35岁，甲多少岁？","options":["30","35","25","50"],"answer":2,"explanation":"【平均数】甲+丙=2×35，乙=2×50-（甲+丙）…由甲+乙=2×40、乙+丙=2×50，得甲=2×40+2×35-2×50再除以2=25岁。"},{"id":"sl-20199","module":"shuliang","diff":2,"prompt":"甲、乙两人的平均年龄是30岁，乙、丙两人的平均年龄是40岁，甲、丙两人的平均年龄是25岁，甲多少岁？","options":["15","25","40","20"],"answer":0,"explanation":"【平均数】甲+丙=2×25，乙=2×40-（甲+丙）…由甲+乙=2×30、乙+丙=2×40，得甲=2×30+2×25-2×40再除以2=15岁。"}]);
